INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(1,'springo','Springo','{"type":"doc","content":[{"type":"image","attrs":{"src":"https://harper-lyre-wiki-api.samuelbunker.workers.dev/api/images/e3fdd0c4-3f47-4be8-9cd5-913b245a19ea.png","alt":null,"title":null}},{"type":"paragraph","content":[{"type":"text","text":"Springo is located inside Bamboo Heights"}]}]}','Sam','Dragonfirebane','2026-08-03 02:49:18','2026-08-03 17:39:26','Springo is located inside Bamboo Heights','{"image":"3b89f172-d466-4b7a-bdeb-2a8632411f1f.png","rows":[{"label":"Located in","value":"Bamboo Heights","link":"bamboo-heights"}]}',1);
INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(2,'bamboo-heights','Bamboo Heights','<p>Harper and Lyre''s first level you''ll adventure through. Bamboo Heights features bamboo, temples, and high heights.</p><figure class="table"><table><thead><tr><th><strong>Friendlies</strong></th><th>Visual</th></tr></thead><tbody><tr><td>Mrs. Boot</td><td><figure class="image image_resized" style="width:98.88%;"><img style="aspect-ratio:200/200;" src="https://harper-lyre-wiki-api.samuelbunker.workers.dev/api/images/520833e7-ccd9-45fd-b17b-4d03ca610758.png" width="200" height="200"></figure></td></tr><tr><td>Mr. Boot</td><td><figure class="image"><img style="aspect-ratio:256/256;" src="https://harper-lyre-wiki-api.samuelbunker.workers.dev/api/images/950132b4-5771-492c-9749-2c8428c6e2ed.gif" width="256" height="256"></figure></td></tr><tr><td>Ren the Dwarf</td><td><figure class="image image_resized" style="width:97.81%;"><img style="aspect-ratio:200/200;" src="https://harper-lyre-wiki-api.samuelbunker.workers.dev/api/images/76181576-fff7-413d-9b51-bba666cc77fc.png" width="200" height="200"></figure></td></tr><tr><td>Sammy Breadington</td><td><figure class="image image_resized" style="width:96.4%;"><img style="aspect-ratio:300/300;" src="https://harper-lyre-wiki-api.samuelbunker.workers.dev/api/images/812e0f6e-8c6b-400d-860c-33aa7dfc2bf5.png" width="300" height="300"></figure></td></tr><tr><td>Cherry Boiz</td><td><figure class="image image_resized" style="width:96.33%;"><img style="aspect-ratio:250/225;" src="https://harper-lyre-wiki-api.samuelbunker.workers.dev/api/images/fa5b7bb6-bafc-4015-b476-f058e473e237.png" width="250" height="225"></figure></td></tr><tr><td>Springo</td><td><figure class="image image_resized" style="width:94.57%;"><img style="aspect-ratio:200/200;" src="https://harper-lyre-wiki-api.samuelbunker.workers.dev/api/images/3b89f172-d466-4b7a-bdeb-2a8632411f1f.png" width="200" height="200"></figure></td></tr><tr><td>Earl D. Fly</td><td><figure class="image image_resized" style="width:100%;"><img style="aspect-ratio:369/368;" src="https://harper-lyre-wiki-api.samuelbunker.workers.dev/api/images/33fee598-160d-48a8-8ba2-0dcfe9c32df2.png" width="369" height="368"></figure><p>&nbsp;</p></td></tr><tr><td>Ritzy Rabbit</td><td><figure class="image image_resized" style="width:98.14%;"><img style="aspect-ratio:250/300;" src="https://harper-lyre-wiki-api.samuelbunker.workers.dev/api/images/84298039-ac60-4874-8cd8-3d8cb48ad19a.png" width="250" height="300"></figure></td></tr></tbody></table></figure><p>&nbsp;</p><figure class="table"><table><tbody><tr><td><strong>Enemies</strong></td><td>&nbsp;</td></tr><tr><td>Rootling</td><td><figure class="image"><img style="aspect-ratio:362/348;" src="https://harper-lyre-wiki-api.samuelbunker.workers.dev/api/images/14d6b253-18cd-468f-85b3-cfd9c6c6f334.png" width="362" height="348"></figure></td></tr><tr><td>Shrublin</td><td><figure class="image"><img style="aspect-ratio:293/302;" src="https://harper-lyre-wiki-api.samuelbunker.workers.dev/api/images/4e48bb96-b724-4f61-9ad0-1dc67836ceb2.png" width="293" height="302"></figure></td></tr><tr><td>Click Clacka</td><td><figure class="image"><img style="aspect-ratio:286/298;" src="https://harper-lyre-wiki-api.samuelbunker.workers.dev/api/images/ce3ad2bb-c8b7-40c6-a36e-c92cc0dd4487.png" width="286" height="298"></figure></td></tr><tr><td>Crusha''s</td><td><figure class="image"><img style="aspect-ratio:461/468;" src="https://harper-lyre-wiki-api.samuelbunker.workers.dev/api/images/dea748b4-8668-45fd-b59f-8408f90de37e.png" width="461" height="468"></figure></td></tr></tbody></table></figure><p>&nbsp;</p><p>&nbsp;</p><p><strong>Friendlies:</strong> Mrs. Boot, Mr. Boot, Ren the Dwarf, Sammy Breadington, Cherry Lads, Springo, Earl D. Fly, Ritzy Rabbit, and Pocus.</p><p><strong>Baddies:</strong> Rootling, Shrublin, Click Clacka, Crusha’s, and The monkey boiz.</p>','Sam','Dragonfirebane','2026-08-03 03:11:41','2026-09-07 18:14:44','Harper and Lyre''s first level you''ll adventure through. Bamboo Heights features bamboo, temples, and high heights. Friendlies Visual Mrs. Boot Mr. Boot Ren the Dwarf Sammy Breadington Cherry Boiz Springo Earl D. Fly &nbsp; Ritzy Rabbit &nbsp; Enemies &nbsp; Rootling Shrublin Click Clacka Crusha''s &nbsp; &nbsp; Friendlies: Mrs. Boot, Mr. Boot, Ren the Dwarf, Sammy Breadington, Cherry Lads, Springo, Earl D. Fly, Ritzy Rabbit, and Pocus. Baddies: Rootling, Shrublin, Click Clacka, Crusha’s, and The monkey boiz.','{"image":"d6a8f14e-aefd-4a37-8a57-6f60c17dd3fd.png","rows":[{"label":"Level 1","value":"Bamboo Heights","links":["bamboo-heights"]},{"label":"Friends","value":"Ren the Dwarf, Springo, Ritzy Rabbit","links":["ren-the-dwarf","springo","ritzy-rabbit"]},{"label":"Meanies","value":"Click Clacka, Rootling, Crusha","links":["enemies","rootling","crusha"]},{"label":"Boss","value":"The Monkey Boiz","links":["the-monkey-boiz"]}]}',1);
INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(3,'mist-side-castle','Mist Side Castle','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mist-Side Castle"}]},{"type":"paragraph","content":[{"type":"text","text":"Spooky shadows roam the halls of the castle, while undead dwellers walk the grounds outside."}]},{"type":"paragraph","content":[{"type":"text","text":"Friendlies: Flicks the ghost (water fountain ghost)"}]},{"type":"paragraph","content":[{"type":"text","text":"Baddies: Dweller (zombie), Ghosti, Skish (skeleton fish), Haunted statue, Shadehand"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Kreakli Rhymes"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"While spooky spectres keep you at bay,"}]},{"type":"paragraph","content":[{"type":"text","text":"maybe I can finish my spell today!"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Halls like a labyrinth, floors made of wood,"}]},{"type":"paragraph","content":[{"type":"text","text":"get out of my mansion, you really should."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Have you had a chance to meet the ghosts inside,"}]},{"type":"paragraph","content":[{"type":"text","text":"you aren''t meant to be here, I thought I clarified."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"H&L Key Locations on Island"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"3 Mist-side Castle;"}]},{"type":"paragraph","content":[{"type":"text","text":"-Graveyard (1)"}]},{"type":"paragraph","content":[{"type":"text","text":"-Mist-side Manor (2)"}]},{"type":"paragraph","content":[{"type":"text","text":"-Murky Walkways (3)"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Fixed Sabercat hat texture on eye"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Mansion Layout"}]},{"type":"paragraph","content":[{"type":"text","text":"The main mansion is made up of four different layers, each containing keys to allow the player to complete the castle."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"The castle starts the player off in the main entrance. Once the player picks up the key, they can take it to the first door. After unlocking the [Entrance Door], players will be able to continue into the castle by walking down to the end of the hallway ahead. Players will pick up and use the [Kitchen Key] on the [Kitchen] Door which unlocks the [Kitchen]."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Inside the [Kitchen] players will proceed to grab the [Star room key] located within the [Fridge]. Players unlock the Fridge by pulling the lever closest to the door, after players are outside the kitchen, within the closet closest to the kitchen is another lever which shuts off the valve system for the [Fridge]."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"After walking into the fridge players can collect the [Star Room Key] and unlock the [Star Room]. Once players have unlocked the [Star room], they must use  [Ledge Climb/Hang] to get across the room ledge to obtain the [Sewing Room Key]. "},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"The player now must press the button next to the Sewing Room Key to have the platforms pop out of the wall and run across them quickly as they will retract back into the wall. Once they reach the Sewing Room, they can walk inside and either pull the lever revealing the door location that is cracked. Or the player can roll/attack/air kick the door down and avoid using the lever for the door light."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Players will obtain the [Diamond Key] which will be used to unlock the next floor up. After walking upstairs to the second floor, players will walk into the closet next to the Library and collect the [Spade Key]. After walking back downstairs to the first floor players can then use the Spade Key on the Spade door unlocking the [Basement]. "},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Once inside the [Basement] players will go into the [Boiler room] to turn on the water systems, allowing them to collect the twisted token inside the fire. Players then must turn off the electricity in the boiler room by transforming into a mouse and breaking the machine from the inside by pressing a button. Then the player can go grab the key behind the exposed electric wires. After players grab the library key, they can unlock the [Library]."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"After entering the library the player can break the panel on the wall to find an elevator allowing them to go to the [Basement] into the blocked room. There the player will find the movie room key. They can take the key back up to the library. After they have the Key to the [Movie Room] the player must climb the stack of books near the room entrance and walk along the vents. After the player gets to the top of the library, they must break the rusty fence in the wall in the back corner. Once the player has walked through the vent shaft they can shell shoot the button on the wall opening the book shelf back up for the [Library]. The player will then either go get the movie room key if not already gone and gotten it, and take it to the door of the [Movie Room]."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Players walk to the end of the hallway and press the button pushing the shelf to the side. Inside the room they have to find the lever hidden behind the movie image screen. Pulling the lever will open the back exit of the [Movie Room]. They must collect the Letter Room Key and unlock the [Letter Room]. Inside the letter room is a puzzle consisting of 4 paintings. All 4 paintings are different, and the player must step on the buttons Starting with Gold, Silver, Platinum, and then Bronze. Once the player has pressed all pressure plates down in this order then the door will open exposing the [Storage Room] Key. "},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"After players unlock the storage room, they must go into the right side of the storage room and shoot a shell at the button behind them as soon as they walk into the room. Bricks and a button will shoot out for about 15 seconds. After 15 seconds, the bridge retracts, and players must hit the shell button a second time. If the player gets across the bridge into the secret room, then they hit the button that opens the elevator allowing them to go to the kitchen storage room. Once inside the Kitchen storage room, players can get on top of the kitchen shelves by jumping on the first cabinet and then the shelf, lastly to the top. Players grab the Heart key giving them access to the final floor which is floor 3."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Players go to the right and grab the observatory key past the door, they bring it to the observatory Door and unlock it. They do a puzzle in the observatory which gives them the key to the green house room. Players grab the green house key and take it through the hole in the top of the observatory side room with a large root guiding them up to it. Players walk through and use the key on the Green house room once they find it. After players unlock the green house room,"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Story board here- Nothing decided for the green house room. Only parkour but i need it to be walking only so we gotta figure it out."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Basement"}]},{"type":"paragraph","content":[{"type":"text","text":"The basement contains the power systems,  wash room, exercise room, and boss room."}]},{"type":"paragraph","content":[{"type":"text","text":"Floor 1"}]},{"type":"paragraph","content":[{"type":"text","text":"The first floor has the kitchen, star room, sewing room, and path up and down a floor."}]},{"type":"paragraph"},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Floor 2"}]},{"type":"paragraph","content":[{"type":"text","text":"The second floor has the library, movie, painting, storage, and path up and down."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Floor 3"}]},{"type":"paragraph","content":[{"type":"text","text":"The third floor has the observatory, green house room, and path downstairs."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Headless Horseman Boss"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Headless Horseman Boss: Dialogue"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, Horseman = HM, Horsey = HE"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Whoa who is that?"}]},{"type":"paragraph","content":[{"type":"text","text":"L: This guy looks scary, maybe we should leave."}]},{"type":"paragraph","content":[{"type":"text","text":"HH: Leave? But you just got here! Why don;t we have some fun?!"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Bring cat a tuna from deep dank waters"}]},{"type":"paragraph","content":[{"type":"text","text":"Schwoomy"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Current Stats"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Baddies: Eagle Warrior, Tribes-man, Tak-tak"}]},{"type":"paragraph","content":[{"type":"text","text":"Level Collectables"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Standard"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Notes (200 / 200)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Buggies (5 / 5)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Cash (3 / 3)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Gold (3 / 3)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Pages (3 / 3)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Panda Coins (2 / 2)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Pixies (3 / 3)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Pocus Tokens (10 / 10)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Twisted Token (20 / 20)"}]}]}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Unique"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]}]}','Dragonfirebane','Sam','2026-08-03 03:16:50','2026-08-03 23:43:26','Mist-Side Castle Spooky shadows roam the halls of the castle, while undead dwellers walk the grounds outside. Friendlies: Flicks the ghost (water fountain ghost) Baddies: Dweller (zombie), Ghosti, Skish (skeleton fish), Haunted statue, Shadehand Kreakli Rhymes While spooky spectres keep you at bay, maybe I can finish my spell today! Halls like a labyrinth, floors made of wood, get out of my mansion, you really should. Have you had a chance to meet the ghosts inside, you aren''t meant to be here, I thought I clarified. H&L Key Locations on Island 3 Mist-side Castle; -Graveyard (1) -Mist-side Manor (2) -Murky Walkways (3) Fixed Sabercat hat texture on eye Mansion Layout The main mansion is made up of four different layers, each containing keys to allow the player to complete the castle. The castle starts the player off in the main entrance. Once the player picks up the key, they can take it to the first door. After unlocking the [Entrance Door], players will be able to continue into the castle by walking down to the end of the hallway ahead. Players will pick up and use the [Kitchen Key] on the [Kitchen] Door which unlocks the [Kitchen]. Inside the [Kitchen] players will proceed to grab the [Star room key] located within the [Fridge]. Players unlock the Fridge by pulling the lever closest to the door, after players are outside the kitchen, within the closet closest to the kitchen is another lever which shuts off the valve system for the [Fridge]. After walking into the fridge players can collect the [Star Room Key] and unlock the [Star Room]. Once players have unlocked the [Star room], they must use  [Ledge Climb/Hang] to get across the room ledge to obtain the [Sewing Room Key].  The player now must press the button next to the Sewing Room Key to have the platforms pop out of the wall and run across them quickly as they will retract back into the wall. Once they reach the Sewing Room, they can walk inside and either pull the lever revealing the door location that is cracked. Or the player can roll/attack/air kick the door down and avoid using the lever for the door light. Players will obtain the [Diamond Key] which will be used to unlock the next floor up. After walking upstairs to the second floor, players will walk into the closet next to the Library and collect the [Spade Key]. After walking back downstairs to the first floor players can then use the Spade Key on the Spade door unlocking the [Basement].  Once inside the [Basement] players will go into the [Boiler room] to turn on the water systems, allowing them to collect the twisted token inside the fire. Players then must turn off the electricity in the boiler room by transforming into a mouse and breaking the machine from the inside by pressing a button. Then the player can go grab the key behind the exposed electric wires. After players grab the library key, they can unlock the [Library]. After entering the library the player can break the panel on the wall to find an elevator allowing them to go to the [Basement] into the blocked room. There the player will find the movie room key. They can take the key back up to the library. After they have the Key to the [Movie Room] the player must climb the stack of books near the room entrance and walk along the vents. After the player gets to the top of the library, they must break the rusty fence in the wall in the back corner. Once the player has walked through the vent shaft they can shell shoot the button on the wall opening the book shelf back up for the [Library]. The player will then either go get the movie room key if not already gone and gotten it, and take it to the door of the [Movie Room]. Players walk to the end of the hallway and press the button pushing the shelf to the side. Inside the room they have to find the lever hidden behind the movie image screen. Pulling the lever will open the back exit of the [Movie Room]. They must collect the Letter Room Key and unlock the [Letter Room]. Inside the letter room is a puzzle consisting of 4 paintings. All 4 paintings are different, and the player must step on the buttons Starting with Gold, Silver, Platinum, and then Bronze. Once the player has pressed all pressure plates down in this order then the door will open exposing the [Storage Room] Key.  After players unlock the storage room, they must go into the right side of the storage room and shoot a shell at the button behind them as soon as they walk into the room. Bricks and a button will shoot out for about 15 seconds. After 15 seconds, the bridge retracts, and players must hit the shell button a second time. If the player gets across the bridge into the secret room, then they hit the button that opens the elevator allowing them to go to the kitchen storage room. Once inside the Kitchen storage room, players can get on top of the kitchen shelves by jumping on the first cabinet and then the shelf, lastly to the top. Players grab the Heart key giving them access to the final floor which is floor 3. Players go to the right and grab the observatory key past the door, they bring it to the observatory Door and unlock it. They do a puzzle in the observatory which gives them the key to the green house room. Players grab the green house key and take it through the hole in the top of the observatory side room with a large root guiding them up to it. Players walk through and use the key on the Green house room once they find it. After players unlock the green house room, Story board here- Nothing decided for the green house room. Only parkour but i need it to be walking only so we gotta figure it out. Basement The basement contains the power systems,  wash room, exercise room, and boss room. Floor 1 The first floor has the kitchen, star room, sewing room, and path up and down a floor. Floor 2 The second floor has the library, movie, painting, storage, and path up and down. Floor 3 The third floor has the observatory, green house room, and path downstairs. Headless Horseman Boss Headless Horseman Boss: Dialogue Key: Harper = H, Lyre = L, Horseman = HM, Horsey = HE H: Whoa who is that? L: This guy looks scary, maybe we should leave. HH: Leave? But you just got here! Why don;t we have some fun?! Bring cat a tuna from deep dank waters Schwoomy Current Stats Baddies: Eagle Warrior, Tribes-man, Tak-tak Level Collectables Standard Notes (200 / 200) Buggies (5 / 5) Cash (3 / 3) Gold (3 / 3) Pages (3 / 3) Panda Coins (2 / 2) Pixies (3 / 3) Pocus Tokens (10 / 10) Twisted Token (20 / 20) Unique','{"image":"3c02f1a8-372a-43b8-bae8-e53c5ac4efeb.png","rows":[{"label":"Level 2","value":"Mist Side Castle","link":"mist-side-castle"},{"label":"NPC''s","value":"Chewy, Crypt Keeper, Mrs. Crow"},{"label":"Baddies","value":"Dweller, Knights, GrokNok"},{"label":"Boss","value":"Headless Horseman","link":"headless-horseman"}]}',1);
INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(4,'trip-trap-tomb','Trip Trap Tomb','<p>Trip Trap Tomb is the 3rd level in Harper and Lyre&nbsp;</p><figure class="table"><table><thead><tr><th><strong>Friendlies</strong></th><th>Visual</th></tr></thead><tbody><tr><td>1</td><td>&nbsp;</td></tr><tr><td>2</td><td>&nbsp;</td></tr><tr><td>3</td><td>&nbsp;</td></tr><tr><td>4</td><td>&nbsp;</td></tr><tr><td>5</td><td>&nbsp;</td></tr><tr><td>6</td><td>&nbsp;</td></tr><tr><td>7</td><td><p>&nbsp;</p><p>&nbsp;</p></td></tr><tr><td>8</td><td>&nbsp;</td></tr></tbody></table></figure>','Dragonfirebane','Dragonfirebane','2026-08-03 03:17:33','2026-09-07 18:38:44','Trip Trap Tomb is the 3rd level in Harper and Lyre&nbsp; Friendlies Visual 1 &nbsp; 2 &nbsp; 3 &nbsp; 4 &nbsp; 5 &nbsp; 6 &nbsp; 7 &nbsp; &nbsp; 8 &nbsp;','{"image":"270a4aec-5ec3-42f8-b725-b6df0939fac1.png","rows":[{"label":"Level 3","value":"Trip Trap Tomb","link":"trip-trap-tomb"}]}',1);
INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(5,'enemies','Click Clacka','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Located inside Bamboo Heights, the click clacka bites, gnaws, and chases you."}]}]}','Dragonfirebane','Dragonfirebane','2026-08-03 03:18:39','2026-08-03 16:25:41','Located inside Bamboo Heights, the click clacka bites, gnaws, and chases you.','{"image":"fc6e90d5-7317-4a66-9b4f-4c7bc798dc99.png","rows":[{"label":"Located in","value":"Bamboo Heights","link":"bamboo-heights"}]}',1);
INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(6,'bosses','Agni','<p>Agni is the third boss of the game, spitting fire balls and spitting flames.</p>','Dragonfirebane','Dragonfirebane','2026-08-03 03:18:58','2026-09-07 17:58:17','Agni is the third boss of the game, spitting fire balls and spitting flames.','{"image":"c2e0faa2-46a0-4dd2-864e-2a72ceefae7d.png","rows":[{"label":"","value":"Trip Trap Tomb","links":["trip-trap-tomb"]}]}',1);
INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(7,'harper-and-lyre','Harper and Lyre','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Harper and lyre the main duo of the game, both together they must defeat kreakli and save Goombalombie island."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Harper and his best friend Lyre are the main protagonist in Harper and Lyre. They both learn moves through their adventure in order to progress through the worlds."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Harper has multiple moves that he can learn such as:"},{"type":"hardBreak"},{"type":"text","text":"Ground pound, attacking, jumping, tail spin, swimming, "}]}]}','Dragonfirebane','Dragonfirebane','2026-08-03 03:19:13','2026-08-03 23:48:37','Harper and lyre the main duo of the game, both together they must defeat kreakli and save Goombalombie island. Harper and his best friend Lyre are the main protagonist in Harper and Lyre. They both learn moves through their adventure in order to progress through the worlds. Harper has multiple moves that he can learn such as: Ground pound, attacking, jumping, tail spin, swimming, ','{"image":"b682c40e-aec1-4b4b-9afc-11d204b6e153.png","rows":[{"label":"Main Character","value":""}]}',1);
INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(8,'berry-basket','Berry Basket','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Berry Basket is found in all levels, by attacking the basket it will spawn 3 strawberries for the player to pick up and heal with."}]}]}','Dragonfirebane','Dragonfirebane','2026-08-03 03:19:53','2026-08-03 17:11:08','Berry Basket is found in all levels, by attacking the basket it will spawn 3 strawberries for the player to pick up and heal with.','{"image":"764240ad-e4c2-42d1-b277-a050a47fde0e.png","rows":[{"label":"Located in","value":"All levels"}]}',1);
