INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(13,'bubba-bee','Bubba Bee','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bubba Bee is located within his estate property near Marigold Fields."},{"type":"hardBreak"},{"type":"text","text":"Behind him sits a secret vault filled to the brim with cash."}]}]}','Dragonfirebane','Dragonfirebane','2026-08-03 03:20:52','2026-08-03 17:32:21','Bubba Bee is located within his estate property near Marigold Fields. Behind him sits a secret vault filled to the brim with cash.','{"image":"b39ba5db-2182-4596-851c-b7bf62382b34.png","rows":[{"label":"Located in","value":"Mairgold Fields","link":"marigold-fields"},{"label":"Wants","value":"Cash","link":"cash"}]}',1);
