INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(16,'chewy','Chewy','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Chewy is located inside Mistside Castle. He wants the player to clear his house of all the creepy zombies otherwise known as Dwellers."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Chewy: Dialogue (Found in misty woods)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, C = Chewy"}]},{"type":"paragraph","content":[{"type":"text","text":"C: The names Chewy, and who are you? Why don’t you look like a zombie?"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"H: You aren’t chasing us down either, but you sure look like an enemy."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"C: I left my town because even the zombies found me creepy and stayed away."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"C: Now I hide in these woods looking for some tasty crows. Do you know where I can find some crow eggs?"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"H: No I’m afraid not Chewy, anything else we could help you with?"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"C: Well if you could manage to clear the zombies from my home, I would give you this token I found from a crow I caught earlier."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"L: I guess we’ll see what we can do about your problem…"}]},{"type":"paragraph","content":[{"type":"text","text":"(Clear the zombies from chewy’s home once)"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"L: Alright you weirdo, we did some house cleaning for you, hand over the token now."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"C: Woohoo, thanks for taking care of me guys, now as promised."}]},{"type":"paragraph","content":[{"type":"text","text":"(Chewy starts to run away)"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"C: My house has the best view of the crows nest, thanks Harper and Lyre!"}]},{"type":"paragraph"}]}','Dragonfirebane','Dragonfirebane','2026-08-03 03:21:43','2026-08-03 18:12:54','Chewy is located inside Mistside Castle. He wants the player to clear his house of all the creepy zombies otherwise known as Dwellers. Chewy: Dialogue (Found in misty woods) Key: Harper = H, Lyre = L, C = Chewy C: The names Chewy, and who are you? Why don’t you look like a zombie? H: You aren’t chasing us down either, but you sure look like an enemy. C: I left my town because even the zombies found me creepy and stayed away. C: Now I hide in these woods looking for some tasty crows. Do you know where I can find some crow eggs? H: No I’m afraid not Chewy, anything else we could help you with? C: Well if you could manage to clear the zombies from my home, I would give you this token I found from a crow I caught earlier. L: I guess we’ll see what we can do about your problem… (Clear the zombies from chewy’s home once) L: Alright you weirdo, we did some house cleaning for you, hand over the token now. C: Woohoo, thanks for taking care of me guys, now as promised. (Chewy starts to run away) C: My house has the best view of the crows nest, thanks Harper and Lyre!','{"image":"ed8b9ff3-2dfd-4999-9c24-04675073a012.png","rows":[{"label":"Located in","value":"Mistside Castle","link":"mist-side-castle"},{"label":"Wants","value":"Clear his house"},{"label":"Rewards","value":"Twisted Token","link":"twisted-token"}]}',1);
INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(17,'crypt-keeper','Crypt Keeper','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Crypt Keeper"}]},{"type":"paragraph","content":[{"type":"text","text":"Activity"}]},{"type":"paragraph","content":[{"type":"text","text":"The crypt keeper: Dialogue"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: C = crypt keeper (says his hints at each numbered location)"}]},{"type":"paragraph","content":[{"type":"text","text":"slam down graves in order for a prize"}]},{"type":"paragraph","content":[{"type":"text","text":"(1: The first one to smash is at grave site 3 where candles are lit.)"}]},{"type":"paragraph","content":[{"type":"text","text":"(1: firstly, candles lit tell the first spot to slam!)"}]},{"type":"paragraph","content":[{"type":"text","text":"C:?????"}]},{"type":"paragraph","content":[{"type":"text","text":"(2: 5 shadow Flowers speak the second location to find and smash.)"}]},{"type":"paragraph","content":[{"type":"text","text":"(2: 5 shadow flowers speak the 2nd spot, smash there!)"}]},{"type":"paragraph","content":[{"type":"text","text":"C:?????"}]},{"type":"paragraph","content":[{"type":"text","text":"(3: The third is 2 and 3 which are lit, next to shadows and pretty flowers.)"}]},{"type":"paragraph","content":[{"type":"text","text":"(3: candles 2 and 3 are lit, nice flowers show a 3rd coffin spot.)"}]},{"type":"paragraph","content":[{"type":"text","text":"C:?????"}]},{"type":"paragraph","content":[{"type":"text","text":"(4: Four of the candles are unlit next to shadows, the grave does not lie.)"}]},{"type":"paragraph","content":[{"type":"text","text":"(4: 4 candles lie dark, have the ghosts taken the light?)"}]},{"type":"paragraph","content":[{"type":"text","text":"C: Two stones and the cliff, find the fourth in the middle of a bend?"}]},{"type":"paragraph","content":[{"type":"text","text":"(5: We buried him with his fifth favorite snack, now he needs jelly.)"}]},{"type":"paragraph","content":[{"type":"text","text":"(5: Jelly thieves Lie buried with spoils on the 5th Spot.)"}]},{"type":"paragraph","content":[{"type":"text","text":"C:Dirt well dug is the fifth target stone, so pay attention!"}]},{"type":"paragraph","content":[{"type":"text","text":"(6: Sixth to smash sits at the base of the hill, but what side?)"}]},{"type":"paragraph","content":[{"type":"text","text":"(6: 6th lies at the base of the hill, but why?)"}]},{"type":"paragraph","content":[{"type":"text","text":"C:?????"}]},{"type":"paragraph","content":[{"type":"text","text":"(7: Some mushrooms grew around the seventh one to smash.))"}]},{"type":"paragraph","content":[{"type":"text","text":"(7: mushrooms surround a 7th coffin, where has my mind gone?!?)"}]},{"type":"paragraph","content":[{"type":"text","text":"C:?????"}]},{"type":"paragraph","content":[{"type":"text","text":"(8: One grave, candle, barrel, and shadow are to smash for eight. (OTHER ITEM REWARD))"}]},{"type":"paragraph","content":[{"type":"text","text":"(8: A grave, candle, barrel, and shadow give an 8th prize. (OTHER ITEM REWARD))"}]},{"type":"paragraph","content":[{"type":"text","text":"C:?????"}]},{"type":"paragraph","content":[{"type":"text","text":"(9: No candles were lit for the final grave near the wooden planks. ))"}]},{"type":"paragraph","content":[{"type":"text","text":"(9: 9th and final coffin, no candles light the way.)"}]},{"type":"paragraph","content":[{"type":"text","text":"C: Cracked stone atop a tall thing, this is the secret, so go find one!"}]}]}','Dragonfirebane','Dragonfirebane','2026-08-03 03:21:53','2026-08-03 18:12:16','The Crypt Keeper Activity The crypt keeper: Dialogue Key: C = crypt keeper (says his hints at each numbered location) slam down graves in order for a prize (1: The first one to smash is at grave site 3 where candles are lit.) (1: firstly, candles lit tell the first spot to slam!) C:????? (2: 5 shadow Flowers speak the second location to find and smash.) (2: 5 shadow flowers speak the 2nd spot, smash there!) C:????? (3: The third is 2 and 3 which are lit, next to shadows and pretty flowers.) (3: candles 2 and 3 are lit, nice flowers show a 3rd coffin spot.) C:????? (4: Four of the candles are unlit next to shadows, the grave does not lie.) (4: 4 candles lie dark, have the ghosts taken the light?) C: Two stones and the cliff, find the fourth in the middle of a bend? (5: We buried him with his fifth favorite snack, now he needs jelly.) (5: Jelly thieves Lie buried with spoils on the 5th Spot.) C:Dirt well dug is the fifth target stone, so pay attention! (6: Sixth to smash sits at the base of the hill, but what side?) (6: 6th lies at the base of the hill, but why?) C:????? (7: Some mushrooms grew around the seventh one to smash.)) (7: mushrooms surround a 7th coffin, where has my mind gone?!?) C:????? (8: One grave, candle, barrel, and shadow are to smash for eight. (OTHER ITEM REWARD)) (8: A grave, candle, barrel, and shadow give an 8th prize. (OTHER ITEM REWARD)) C:????? (9: No candles were lit for the final grave near the wooden planks. )) (9: 9th and final coffin, no candles light the way.) C: Cracked stone atop a tall thing, this is the secret, so go find one!','{"image":"76b7f255-61e6-4556-9484-6b8f106cfe7a.png","rows":[]}',1);
