INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(19,'flicks-the-ghost','Flicks the Ghost','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Flicks the Ghost is located inside Mistside Castle near the fountain"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Flicks the Ghost: Dialogue"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, FG = Flicks the ghost"}]},{"type":"paragraph","content":[{"type":"text","text":"FG: My name is Flicks, and  I’m so sad now that all of my fountain water’s gone!"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"L: What do you need water for, you’re just a ghost!"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"H: Lyre, that’s no way to talk to our new friend. Is there some way to run water to your fountain?"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: Yes but you need to get inside the mansion to turn it on. I have the water wheel you need."},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"FG: But im too scared of ghosts to go inside the mansion."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"L: I guess I should break it to you then buddy."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: No, I''m sorry but I''m not a ghost. I am an aberration."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"H: We can help by tuning the water back on for you."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"L: Yea, hand over the water wheel and a token and we will turn it on."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: I’ll give you the water wheel but I don’t have a token, Bunchin took it."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"L: Who’s Bunchin?"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: He’s the new grounds keeper, he thinks watering the flowers is a waste."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: But I know this flower is special and it needs just one more watering before it blooms."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"(Activate the water line somewhere in the castle)"},{"type":"hardBreak"},{"type":"text","text":"H: There we go flicks, now you have plenty of water."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"FG: I watch over the flowers now in the castle yard, since Bunchin ran away."},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"FG: I was right, this flower finally bloomed, here take this mysterious wooden thing that came out of it."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"L: Appreciate you Flicks, ok now how much more do we need to find?"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"H: Quite a lot Lyre, so lets move."}]},{"type":"paragraph"}]}','Dragonfirebane','Dragonfirebane','2026-08-03 03:23:26','2026-08-03 18:16:08','Flicks the Ghost is located inside Mistside Castle near the fountain Flicks the Ghost: Dialogue Key: Harper = H, Lyre = L, FG = Flicks the ghost FG: My name is Flicks, and  I’m so sad now that all of my fountain water’s gone! L: What do you need water for, you’re just a ghost! H: Lyre, that’s no way to talk to our new friend. Is there some way to run water to your fountain? FG: Yes but you need to get inside the mansion to turn it on. I have the water wheel you need. FG: But im too scared of ghosts to go inside the mansion. L: I guess I should break it to you then buddy. FG: No, I''m sorry but I''m not a ghost. I am an aberration. H: We can help by tuning the water back on for you. L: Yea, hand over the water wheel and a token and we will turn it on. FG: I’ll give you the water wheel but I don’t have a token, Bunchin took it. L: Who’s Bunchin? FG: He’s the new grounds keeper, he thinks watering the flowers is a waste. FG: But I know this flower is special and it needs just one more watering before it blooms. (Activate the water line somewhere in the castle) H: There we go flicks, now you have plenty of water. FG: I watch over the flowers now in the castle yard, since Bunchin ran away. FG: I was right, this flower finally bloomed, here take this mysterious wooden thing that came out of it. L: Appreciate you Flicks, ok now how much more do we need to find? H: Quite a lot Lyre, so lets move.','{"image":"a125af78-d58e-4393-87b1-46410ce66408.png","rows":[{"label":"Location","value":"Mistside Castle","link":"mist-side-castle"},{"label":"Rewards","value":"Twisted Token","link":"twisted-token"},{"label":"Wants","value":"Water for his flowers outside the mansion"}]}',1);
