INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(34,'mrs-crow','Mrs. Crow','<p>Mrs. Crow: Dialogue (Found ???)</p><p>Key: Harper = H, Lyre = L, C = mrs. crow</p><p>C: Oh boo hoo, can’t anybody out there help me with my problem!</p><p>L: That depends, is the reward in it for us?</p><p>H: Lyre! That’s no way to talk to someone in need, now tell us what your issue is.</p><p>C: Well… the name’s Mrs. Crow and I just can’t find my husband anywhere!</p><p>L: “I don’t think I should tell her what happened…” (whispers)</p><p>H: Where was the last place that you found them?</p><p>C: He… was set up to guard the eggs in the nest, but I just don’t know where he is now! Boo hoo hoo!</p><p>H: Alright alright, we’ll look for him.</p><p>&nbsp;</p><p>(Mr. crow can be found trapped under rubble in Firestone mountain, can be broken with a ground pound, the two talk in Firestone mountain)</p><p>&nbsp;</p><p>H: We found him and brought him home to you, is there anything else you needed?</p><p>L: Oh no not another task…</p><p>C: No… Thank you so much for finding him, take this token that I had all along.</p>','Dragonfirebane','Sam','2026-08-03 03:26:03','2026-08-04 00:54:35','Mrs. Crow: Dialogue (Found ???) Key: Harper = H, Lyre = L, C = mrs. crow C: Oh boo hoo, can’t anybody out there help me with my problem! L: That depends, is the reward in it for us? H: Lyre! That’s no way to talk to someone in need, now tell us what your issue is. C: Well… the name’s Mrs. Crow and I just can’t find my husband anywhere! L: “I don’t think I should tell her what happened…” (whispers) H: Where was the last place that you found them? C: He… was set up to guard the eggs in the nest, but I just don’t know where he is now! Boo hoo hoo! H: Alright alright, we’ll look for him. &nbsp; (Mr. crow can be found trapped under rubble in Firestone mountain, can be broken with a ground pound, the two talk in Firestone mountain) &nbsp; H: We found him and brought him home to you, is there anything else you needed? L: Oh no not another task… C: No… Thank you so much for finding him, take this token that I had all along.','{"image":"e83221df-a5bf-4435-b29e-2de12a8daa06.png","rows":[{"label":"Location","value":"Mistside Castle","link":"mist-side-castle"},{"label":"Wants","value":"Find her husband Mr. Crow"},{"label":"Rewards","value":"Twisted Token","link":"twisted-token"}]}',1);
