INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(41,'sticks-and-mips','Sticks and Mips','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two cats rhyming with great timing. These two cats are sitting on a tree inside Mistside Castle"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Sticks and Mips: Dialogue (Found on a tree together)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, S = Sticks, M = Mips"}]},{"type":"paragraph","content":[{"type":"text","text":"S: We are cats you see, my name’s Sticks."}]},{"type":"paragraph","content":[{"type":"text","text":"M: My name’s Mips, a curious little one!"}]},{"type":"paragraph","content":[{"type":"text","text":"S: We are Sticks and Mips, the cat duo!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: You would think the two of you would rhyme at least, being a duo and all."}]},{"type":"paragraph","content":[{"type":"text","text":"L: What’s wrong, cat got your tongue?"}]},{"type":"paragraph","content":[{"type":"text","text":"S: I do not get the joke, you two must find a way to reach the top tree branch!"}]},{"type":"paragraph","content":[{"type":"text","text":"M: Yes, the top branch will earn our respect, if you can’t then no reward for you!"}]},{"type":"paragraph","content":[{"type":"text","text":"L: Ok, but how are we supposed to do that?"}]},{"type":"paragraph","content":[{"type":"text","text":"H: The top of the tree is too high for us, but I suppose we can try and find a way."}]},{"type":"paragraph"}]}','Dragonfirebane','Dragonfirebane','2026-08-03 03:27:14','2026-08-03 18:18:43','Two cats rhyming with great timing. These two cats are sitting on a tree inside Mistside Castle Sticks and Mips: Dialogue (Found on a tree together) Key: Harper = H, Lyre = L, S = Sticks, M = Mips S: We are cats you see, my name’s Sticks. M: My name’s Mips, a curious little one! S: We are Sticks and Mips, the cat duo! H: You would think the two of you would rhyme at least, being a duo and all. L: What’s wrong, cat got your tongue? S: I do not get the joke, you two must find a way to reach the top tree branch! M: Yes, the top branch will earn our respect, if you can’t then no reward for you! L: Ok, but how are we supposed to do that? H: The top of the tree is too high for us, but I suppose we can try and find a way.','{"image":"be7aba4f-860d-45e3-ac6d-f455163ee5ef.png","rows":[{"label":"Located In","value":"Mistside Castle","link":"mist-side-castle"},{"label":"Wants","value":"Solve their riddle"},{"label":"Reward","value":"Twisted Token","link":"twisted-token"}]}',1);
