INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(116,'the-great-bird','Cherry Boiz','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cherry Lads: Dialogue"}]},{"type":"paragraph","content":[{"type":"text","text":"Cherry Boiz: Hey you two help us, quickly before the shrublins come back."}]},{"type":"paragraph","content":[{"type":"text","text":"Harper: Shrublins? What is a shrublin?"}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: I think this cherry has lost it Harper."}]},{"type":"paragraph","content":[{"type":"text","text":"Cherry Boiz: Shrublins are eating us, they wont let us escape."}]},{"type":"paragraph","content":[{"type":"text","text":"Cherry Boiz: You have to save us from these meanies."}]},{"type":"paragraph","content":[{"type":"text","text":"Cherry Boiz: Each cherry you save is worth 1, 2, or 3 points, save at least 35 of us."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: I don''t want to help them Harper, let’s watch them get eaten."}]},{"type":"paragraph","content":[{"type":"text","text":"Harper: Lyre! Don''t worry, we will help you."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: Aw but I wanted to watch them run around."}]}]}','Dragonfirebane','Dragonfirebane','2026-08-03 16:08:23','2026-08-03 17:37:28','Cherry Lads: Dialogue Cherry Boiz: Hey you two help us, quickly before the shrublins come back. Harper: Shrublins? What is a shrublin? Lyre: I think this cherry has lost it Harper. Cherry Boiz: Shrublins are eating us, they wont let us escape. Cherry Boiz: You have to save us from these meanies. Cherry Boiz: Each cherry you save is worth 1, 2, or 3 points, save at least 35 of us. Lyre: I don''t want to help them Harper, let’s watch them get eaten. Harper: Lyre! Don''t worry, we will help you. Lyre: Aw but I wanted to watch them run around.','{"image":"fa5b7bb6-bafc-4015-b476-f058e473e237.png","rows":[{"label":"Located in","value":"Bamboo Heights","link":"bamboo-heights"},{"label":"Wants","value":"Help save Cherry Friends"},{"label":"Rewards","value":"Twisted Token","link":"twisted-token"}]}',1);
INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(117,'note-door','Note Door','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Note doors are unlocked with Notes, players run around the level and collect the notes allowing them to get further into the Sub worlds."}]}]}','Dragonfirebane','Dragonfirebane','2026-08-03 16:14:36','2026-08-03 16:19:40','Note doors are unlocked with Notes, players run around the level and collect the notes allowing them to get further into the Sub worlds.','{"image":"a196adc9-886a-40f6-bbf5-6cd30636bf0d.png","rows":[{"label":"Unlock with","value":"Notes","link":"notes"},{"label":"Located In","value":"Sub Worlds","link":"the-grasslands"}]}',1);
