INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(119,'bunchin','Bunchin','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bunchin: Dialogue (Found in lumbermill)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, B = Bunchin"}]},{"type":"paragraph","content":[{"type":"text","text":"B: Oh boy am I crazy, the name’s Bunchin chums, who might you be, hoo wee!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: I’m Harper what is the deal with you buddy?"}]},{"type":"paragraph","content":[{"type":"text","text":"B: I’m gonna bite you in the legs, but wait, just a moment."}]},{"type":"paragraph","content":[{"type":"text","text":"L: Uhhh, my name’s… Lyre, are you some kind of whacko?"}]},{"type":"paragraph","content":[{"type":"text","text":"B: No sir no sir no sir!!! My machine’s stopped workin, gotta cut the logs for the man in the city you see. Figure out how to solve my issue, or I just can’t give you this token I found in the woods earlier!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: We’ll try to find something for you, let''s go Lyre."}]},{"type":"paragraph","content":[{"type":"text","text":"L: “I’d leave this weirdo alone if you ask me”. (whisper)"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"(The two activate a switch outside guarded by ghosts)"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"H: Alright, those guys sure scared us, but we’ve started up your machine again Bunchin."}]},{"type":"paragraph","content":[{"type":"text","text":"L: Hand over that token you promised, don’t chicken out!"}]},{"type":"paragraph","content":[{"type":"text","text":"B: Creepy wacky friends! Take a token, take it, take it!"}]},{"type":"paragraph"}]}','Dragonfirebane','Dragonfirebane','2026-08-03 18:18:18','2026-08-03 18:18:18','Bunchin: Dialogue (Found in lumbermill) Key: Harper = H, Lyre = L, B = Bunchin B: Oh boy am I crazy, the name’s Bunchin chums, who might you be, hoo wee! H: I’m Harper what is the deal with you buddy? B: I’m gonna bite you in the legs, but wait, just a moment. L: Uhhh, my name’s… Lyre, are you some kind of whacko? B: No sir no sir no sir!!! My machine’s stopped workin, gotta cut the logs for the man in the city you see. Figure out how to solve my issue, or I just can’t give you this token I found in the woods earlier! H: We’ll try to find something for you, let''s go Lyre. L: “I’d leave this weirdo alone if you ask me”. (whisper) (The two activate a switch outside guarded by ghosts) H: Alright, those guys sure scared us, but we’ve started up your machine again Bunchin. L: Hand over that token you promised, don’t chicken out! B: Creepy wacky friends! Take a token, take it, take it!','{"image":"8ce69462-8228-4dbe-a2ed-8684c2292ce1.png","rows":[{"label":"Location","value":"Mistside Castle","link":"mist-side-castle"},{"label":"Wants","value":"Level Collectable","link":"level-specific-collectables"},{"label":"Rewards","value":"Twisted Token and Page"}]}',1);
INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(120,'about','About','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Harper and Lyre is a game about a red panda named Harper and his best friend Lyre the Otter. Harper and Lyre go everywhere together, from mountain climbing to the deepest depths of the ocean, their adventures know no bounds. Explore the entire game which contains up to 18 levels."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Harper and Lyre started out as a High resolution game at first development. It was shelved temporarily to in an attempt to create a VR game. After the VR game was scrapped we decided as a two person team to power down on Harper and Lyre and create something unforgettable."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"I was the first puzzle piece, the one who started it all. When I heard of unreal engine 4 I started creating Harper and Lyre. I needed a name, and I couldn''t do just any name. It had to be silly, strange, weird, But most important, it had to be right! I had started learning to play the lyre at the time, which was really cool. I then thought what instrument would go well with it? What about a harp? then ER was added to it to make it right, and this entire adventure began. Oh what an adventure it has been."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"In the development process of our previous game we obtained our second puzzle piece, George. He is now our Lead artist for everything in Harper and Lyre!"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"After about 3 total years of development of Harper and Lyre, we acquired our third piece of the puzzle, Sam. He handles our Website needs such as the very one your reading now! He also does a small portion of the coding on the side."}]}]}','Dragonfirebane','Dragonfirebane','2026-08-03 18:35:45','2026-08-03 18:35:45','Harper and Lyre is a game about a red panda named Harper and his best friend Lyre the Otter. Harper and Lyre go everywhere together, from mountain climbing to the deepest depths of the ocean, their adventures know no bounds. Explore the entire game which contains up to 18 levels. Harper and Lyre started out as a High resolution game at first development. It was shelved temporarily to in an attempt to create a VR game. After the VR game was scrapped we decided as a two person team to power down on Harper and Lyre and create something unforgettable. I was the first puzzle piece, the one who started it all. When I heard of unreal engine 4 I started creating Harper and Lyre. I needed a name, and I couldn''t do just any name. It had to be silly, strange, weird, But most important, it had to be right! I had started learning to play the lyre at the time, which was really cool. I then thought what instrument would go well with it? What about a harp? then ER was added to it to make it right, and this entire adventure began. Oh what an adventure it has been. In the development process of our previous game we obtained our second puzzle piece, George. He is now our Lead artist for everything in Harper and Lyre! After about 3 total years of development of Harper and Lyre, we acquired our third piece of the puzzle, Sam. He handles our Website needs such as the very one your reading now! He also does a small portion of the coding on the side.','{"image":"cb271ed1-871a-400b-97a2-f2ca8316bf98.png","rows":[{"label":"Currently rated (not officially) but by me","value":"E 10+"}]}',1);
