INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(125,'frog-boss-kreaklis-bog','Frog Boss Kreaklis bog','<p>The frog is the boss of level 6, kreaklis bog</p>','Dragonfirebane','Dragonfirebane','2026-09-07 18:00:56','2026-09-07 18:00:56','The frog is the boss of level 6, kreaklis bog','{"rows":[{"label":"","value":"Kreaklis Bog","links":["kreaklis-bog"]}]}',1);
INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(126,'sligma','Sligma','<p>Sligma is the boss of Firestone Mountain, and shoots fire balls into the air like a shower of fire rocks.</p>','Dragonfirebane','Dragonfirebane','2026-09-07 18:02:16','2026-09-07 18:02:33','Sligma is the boss of Firestone Mountain, and shoots fire balls into the air like a shower of fire rocks.','{"image":"fbc5bdfd-303d-4b9a-b5b1-055008d248e4.png","rows":[{"label":"","value":"Fire Stone Mountain","links":["fire-stone-mountain"]}]}',1);
INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(127,'blizzy-the-walrus','Blizzy the walrus ','<p>Blizzy the walrus is the boss in SnowShow City, players must out dance and outshine him in order to win.</p>','Dragonfirebane','Dragonfirebane','2026-09-07 18:06:55','2026-09-07 18:06:55','Blizzy the walrus is the boss in SnowShow City, players must out dance and outshine him in order to win.','{"rows":[{"label":"","value":"Snow Show City","links":["snow-show-city"]}]}',1);
INSERT INTO "pages" ("id","slug","title","content","created_by","updated_by","created_at","updated_at","content_text","infobox","published") VALUES(128,'larry-the-vulture','Larry the vulture','<p>Larry the Vulture is the boss of WesternCliffs.</p>','Dragonfirebane','Dragonfirebane','2026-09-07 18:08:08','2026-09-07 18:08:08','Larry the Vulture is the boss of WesternCliffs.','{"rows":[{"label":"","value":"Western Cliffs","links":["western-cliffs"]}]}',1);
