INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(82,79,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"There are a total of 5 in each world."},{"type":"hardBreak"},{"type":"text","text":"They are used in gaining additional oxygen from Bufweeble."}]}]}','Dragonfirebane','2026-08-03 16:06:40');
