INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(96,2,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bamboo Heights"}]},{"type":"paragraph","content":[{"type":"text","text":"A level filled with bamboo, temples, and heights."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]},{"type":"paragraph","content":[{"type":"text","text":"Friendlies:Mrs. Boot, Mr. Boot, Ren the Dwarf, Sammy Breadington, Cherry Lads, Springo, Earl D. Fly, Ritzy Rabbit, and Pocus."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]},{"type":"paragraph","content":[{"type":"text","text":"Baddies: Rootling, Shrublin, Click Clacka, Crusha’s, and The monkey boiz."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]},{"type":"paragraph","content":[{"type":"text","text":"Twisted Token Locations"}]},{"type":"paragraph","content":[{"type":"text","text":"1. Race through the hoop mini game to find a token."}]},{"type":"paragraph","content":[{"type":"text","text":"2. Beat the level boss, The Monkey Boiz to acquire a token."}]},{"type":"paragraph","content":[{"type":"text","text":"3. Get all Flazoozles in the level to get a twisted token."}]},{"type":"paragraph","content":[{"type":"text","text":"4. Inside the cave above to the monkey boy’s (Needs Monkey)"},{"type":"hardBreak"},{"type":"text","text":"5. Next to Pocus’s house on the hill."}]},{"type":"paragraph","content":[{"type":"text","text":"6. Talk with Earl D. Fly, get his cane, and return it to obtain a twisted token."}]},{"type":"paragraph","content":[{"type":"text","text":"7. At the bottom of the dried up fishing pond. "}]},{"type":"paragraph","content":[{"type":"text","text":"8. Top of temple"}]},{"type":"paragraph","content":[{"type":"text","text":"9. Get Mr. boot back to Mrs. boot"}]},{"type":"paragraph","content":[{"type":"text","text":"10. Behind Springo’s house"}]},{"type":"paragraph","content":[{"type":"text","text":"11. Inside Springo’s house"}]},{"type":"paragraph","content":[{"type":"text","text":"12. Catch the cherry lads mini game."}]},{"type":"paragraph","content":[{"type":"text","text":"13. On top of the fountain inside the temple."}]},{"type":"paragraph","content":[{"type":"text","text":"14. Climb up the vines at the tree house. (As a monkey)"}]},{"type":"paragraph","content":[{"type":"text","text":"15. Top of the cliff inside the house."}]},{"type":"paragraph","content":[{"type":"text","text":"16. Behind the web inside the cave."}]},{"type":"paragraph","content":[{"type":"text","text":"17.  Third floor inside the temple."}]},{"type":"paragraph","content":[{"type":"text","text":"18. Climb the vines on the left side of the temple. (As Monkey)"}]},{"type":"paragraph","content":[{"type":"text","text":"19. Race Ritzy Rabbit and win."}]},{"type":"paragraph","content":[{"type":"text","text":"20. Collect 10 Jellies for Sammy Breadington."}]},{"type":"paragraph","content":[{"type":"text","text":"Collectable Locations"}]},{"type":"paragraph","content":[{"type":"text","text":"PAges"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Defeat Ritzy in the race for the second time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Give Sammy BreadingTon 20 Jelly Jars"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Shoot Ladder down at base of mountain"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Panda coins"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the bench after you go over the first hill on the right."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hidden inside the three bamboo trunks near Mr. Boot."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Under Pocus’s House"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Pixies"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Behind Sammy Breadington’s Jelly jar."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Next to Pocus’s house."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Gold"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inside the cave around the entrance."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"At the back of the level right of Springo’s house."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"At the beginning on top of the hill close to Hugo"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Buggies"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the log next to the hoop mini game switch."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the hill next to the dried up pond."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On top of the dirt mound near the tree house."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On top of one of the cherry tree roots,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On top of the chopped down cherry tree next to the temple."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Pocus Tokens"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Behind Brs Boot’s barn"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"At the beginning of the level "}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On log behind the temple."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the cliffs near Mrs. Boot’s barn."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Near the Hoop mini game button."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the roots of the cherry tree."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"At the J near the Cherry lads."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"At the J near Pocus’s house."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Between the caves and tree house."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inside Pocus''s house through the chimney."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Cash"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"In the corner next to Earl De Fly."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Next to the mountain entrance."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On a bench at the base of the temple."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Secret Floppy Location"}]},{"type":"paragraph","content":[{"type":"text","text":"Behind the poster/flag inside the tree house, must hit gong before going inside it."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]},{"type":"paragraph","content":[{"type":"text","text":"Fruit Fly: Dialogue"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, F = fruit fly"}]},{"type":"paragraph","content":[{"type":"text","text":"F: Hi Harper and Lyre, you two are the best!"}]},{"type":"paragraph","content":[{"type":"text","text":"L: Well well well, this is what im talking about, our own fan club."}]},{"type":"paragraph","content":[{"type":"text","text":"F: I’ll be your fan as long as I live!"}]},{"type":"paragraph","content":[{"type":"text","text":"F: Can you help me by finding me a cane for when I get old?"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Anything for a fan, come on Lyre, let''s help him."}]},{"type":"paragraph","content":[{"type":"text","text":"L: I mean he is our fan, so that works for me."}]},{"type":"paragraph","content":[{"type":"text","text":"(Player gives them Cane)"}]},{"type":"paragraph","content":[{"type":"text","text":"F: Thanks guys, that’s why I''m your biggest fan!"}]},{"type":"paragraph","content":[{"type":"text","text":"F: If you wouldn’t mind, I can’t use this cane with you watching."}]},{"type":"paragraph","content":[{"type":"text","text":"(Player leaves and comes back)"}]},{"type":"paragraph","content":[{"type":"text","text":"F: Well look who it is, Harper and Lyre!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: What happened to you, we just left?"}]},{"type":"paragraph","content":[{"type":"text","text":"F: We fruit flies age fast, but not to worry as I still have my wits."}]},{"type":"paragraph","content":[{"type":"text","text":"L: What you have is bad genetics..."}]},{"type":"paragraph","content":[{"type":"text","text":"H: Lyre don''t be rude."}]},{"type":"paragraph","content":[{"type":"text","text":"F: It''s ok, thank you for helping me, now here''s a token."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren the Dwarf: Dialogue"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: Well now what do we have here, a couple of punks. What do you want?"},{"type":"hardBreak"},{"type":"text","text":"Lyre: I like this guy Harper. He reminds me of me."}]},{"type":"paragraph","content":[{"type":"text","text":"Harper: Sorry for bothering you."}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: First a giant tree attacks me, now a dumb otter annoys me."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: Let''s go, Harper. This guy is an angry little elf."}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: ELF?! Are you out of your mind!"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: If I had my ore I would not be here right now."}]},{"type":"paragraph","content":[{"type":"text","text":"Harper: Settle down you two, what happened?"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: This giant tree tricked me and stole the last 5 pieces of my ore."}]},{"type":"paragraph","content":[{"type":"text","text":"Harper: What can we do to help?"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: Get my ore inside the house up the mountain, but watch out for Crusha''s."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: What''s a Crusha? It sounds dumb, like you."}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: It''s a big rock, they crush you. Sent me flying last week."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: What''s in it for us?"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: I''ve got this wooden doo-dad that I was going to burn."}]},{"type":"paragraph","content":[{"type":"text","text":"Harper: That sounds like a deal, don''t worry Ren we will help you."}]},{"type":"paragraph","content":[{"type":"text","text":"—----------------------------------------------------------Second Ren—-------"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: Took you long enough. Did you get my emeralds?"}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: We got your rubies, not your emeralds."}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: Rubies? These are clearly emeralds."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: What, no way, these are rubies!"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: You must be color blind, these are emeralds."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: You’ve lost it Ren, just give us the token."}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: Even though you''re blind and dumb, you helped me so here."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]},{"type":"paragraph","content":[{"type":"text","text":"Cherry Lads: Dialogue"}]},{"type":"paragraph","content":[{"type":"text","text":"Cherry Boiz: Hey you two help us, quickly before the shrublins come back."}]},{"type":"paragraph","content":[{"type":"text","text":"Harper: Shrublins? What is a shrublin?"}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: I think this cherry has lost it Harper."}]},{"type":"paragraph","content":[{"type":"text","text":"Cherry Boiz: Shrublins are eating us, they wont let us escape."}]},{"type":"paragraph","content":[{"type":"text","text":"Cherry Boiz: You have to save us from these meanies."}]},{"type":"paragraph","content":[{"type":"text","text":"Cherry Boiz: Each cherry you save is worth 1, 2, or 3 points, save at least 35 of us."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: I don''t want to help them Harper, let’s watch them get eaten."}]},{"type":"paragraph","content":[{"type":"text","text":"Harper: Lyre! Don''t worry, we will help you."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: Aw but I wanted to watch them run around."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]}]}','Dragonfirebane','2026-08-03 16:30:12');
