INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(118,38,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sammy BreadingTon is located inside Bamboo Heights, requiring the player to bring him the level collectable of jelly jars. He wishes to rub it all over his face."}]}]}','Dragonfirebane','2026-08-03 17:22:01');
