INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(122,116,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cherry Lads: Dialogue"}]},{"type":"paragraph","content":[{"type":"text","text":"Cherry Boiz: Hey you two help us, quickly before the shrublins come back."}]},{"type":"paragraph","content":[{"type":"text","text":"Harper: Shrublins? What is a shrublin?"}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: I think this cherry has lost it Harper."}]},{"type":"paragraph","content":[{"type":"text","text":"Cherry Boiz: Shrublins are eating us, they wont let us escape."}]},{"type":"paragraph","content":[{"type":"text","text":"Cherry Boiz: You have to save us from these meanies."}]},{"type":"paragraph","content":[{"type":"text","text":"Cherry Boiz: Each cherry you save is worth 1, 2, or 3 points, save at least 35 of us."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: I don''t want to help them Harper, let’s watch them get eaten."}]},{"type":"paragraph","content":[{"type":"text","text":"Harper: Lyre! Don''t worry, we will help you."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: Aw but I wanted to watch them run around."}]}]}','Dragonfirebane','2026-08-03 17:37:28');
