INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(132,75,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"There are a total of 9 different Flazoozles to collect."},{"type":"hardBreak"},{"type":"text","text":"After the player collects all 9 within one main world they are rewarded with a twisted token."}]}]}','Dragonfirebane','2026-08-03 18:01:08');
INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(133,7,'{"type":"doc","content":[{"type":"paragraph"}]}','Dragonfirebane','2026-08-03 18:04:33');
