INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(136,3,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mist-Side Castle"}]},{"type":"paragraph","content":[{"type":"text","text":"Spooky shadows roam the halls of the castle, while undead dwellers walk the grounds outside."}]},{"type":"paragraph","content":[{"type":"text","text":"Friendlies: Flicks the ghost (water fountain ghost)"}]},{"type":"paragraph","content":[{"type":"text","text":"Baddies: Dweller (zombie), Ghosti, Skish (skeleton fish), Haunted statue, Shadehand"}]},{"type":"paragraph","content":[{"type":"text","text":"The Crypt Keeper"}]},{"type":"paragraph","content":[{"type":"text","text":"Activity"}]},{"type":"paragraph","content":[{"type":"text","text":"The crypt keeper: Dialogue"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: C = crypt keeper (says his hints at each numbered location)"}]},{"type":"paragraph","content":[{"type":"text","text":"slam down graves in order for a prize"}]},{"type":"paragraph","content":[{"type":"text","text":"(1: The first one to smash is at grave site 3 where candles are lit.)"}]},{"type":"paragraph","content":[{"type":"text","text":"(1: firstly, candles lit tell the first spot to slam!)"}]},{"type":"paragraph","content":[{"type":"text","text":"C:?????"}]},{"type":"paragraph","content":[{"type":"text","text":"(2: 5 shadow Flowers speak the second location to find and smash.)"}]},{"type":"paragraph","content":[{"type":"text","text":"(2: 5 shadow flowers speak the 2nd spot, smash there!)"}]},{"type":"paragraph","content":[{"type":"text","text":"C:?????"}]},{"type":"paragraph","content":[{"type":"text","text":"(3: The third is 2 and 3 which are lit, next to shadows and pretty flowers.)"}]},{"type":"paragraph","content":[{"type":"text","text":"(3: candles 2 and 3 are lit, nice flowers show a 3rd coffin spot.)"}]},{"type":"paragraph","content":[{"type":"text","text":"C:?????"}]},{"type":"paragraph","content":[{"type":"text","text":"(4: Four of the candles are unlit next to shadows, the grave does not lie.)"}]},{"type":"paragraph","content":[{"type":"text","text":"(4: 4 candles lie dark, have the ghosts taken the light?)"}]},{"type":"paragraph","content":[{"type":"text","text":"C: Two stones and the cliff, find the fourth in the middle of a bend?"}]},{"type":"paragraph","content":[{"type":"text","text":"(5: We buried him with his fifth favorite snack, now he needs jelly.)"}]},{"type":"paragraph","content":[{"type":"text","text":"(5: Jelly thieves Lie buried with spoils on the 5th Spot.)"}]},{"type":"paragraph","content":[{"type":"text","text":"C:Dirt well dug is the fifth target stone, so pay attention!"}]},{"type":"paragraph","content":[{"type":"text","text":"(6: Sixth to smash sits at the base of the hill, but what side?)"}]},{"type":"paragraph","content":[{"type":"text","text":"(6: 6th lies at the base of the hill, but why?)"}]},{"type":"paragraph","content":[{"type":"text","text":"C:?????"}]},{"type":"paragraph","content":[{"type":"text","text":"(7: Some mushrooms grew around the seventh one to smash.))"}]},{"type":"paragraph","content":[{"type":"text","text":"(7: mushrooms surround a 7th coffin, where has my mind gone?!?)"}]},{"type":"paragraph","content":[{"type":"text","text":"C:?????"}]},{"type":"paragraph","content":[{"type":"text","text":"(8: One grave, candle, barrel, and shadow are to smash for eight. (OTHER ITEM REWARD))"}]},{"type":"paragraph","content":[{"type":"text","text":"(8: A grave, candle, barrel, and shadow give an 8th prize. (OTHER ITEM REWARD))"}]},{"type":"paragraph","content":[{"type":"text","text":"C:?????"}]},{"type":"paragraph","content":[{"type":"text","text":"(9: No candles were lit for the final grave near the wooden planks. ))"}]},{"type":"paragraph","content":[{"type":"text","text":"(9: 9th and final coffin, no candles light the way.)"}]},{"type":"paragraph","content":[{"type":"text","text":"C: Cracked stone atop a tall thing, this is the secret, so go find one!"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Chewy: Dialogue (Found in misty woods)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, C = Chewy"}]},{"type":"paragraph","content":[{"type":"text","text":"C: The names Chewy, and who are you? Why don’t you look like a zombie?"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"H: You aren’t chasing us down either, but you sure look like an enemy."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"C: I left my town because even the zombies found me creepy and stayed away."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"C: Now I hide in these woods looking for some tasty crows. Do you know where I can find some crow eggs?"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"H: No I’m afraid not Chewy, anything else we could help you with?"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"C: Well if you could manage to clear the zombies from my home, I would give you this token I found from a crow I caught earlier."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"L: I guess we’ll see what we can do about your problem…"}]},{"type":"paragraph","content":[{"type":"text","text":"(Clear the zombies from chewy’s home once)"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"L: Alright you weirdo, we did some house cleaning for you, hand over the token now."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"C: Woohoo, thanks for taking care of me guys, now as promised."}]},{"type":"paragraph","content":[{"type":"text","text":"(Chewy starts to run away)"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"C: My house has the best view of the crows nest, thanks Harper and Lyre!"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Flicks the Ghost: Dialogue (Found in graveyard by fountain)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, FG = Flicks the ghost"}]},{"type":"paragraph","content":[{"type":"text","text":"FG: My name is Flicks, and  I’m so sad now that all of my fountain water’s gone!"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"L: What do you need water for, you’re just a ghost!"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"H: Lyre, that’s no way to talk to our new friend. Is there some way to run water to your fountain?"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: Yes but you need to get inside the mansion to turn it on. I have the water wheel you need."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"FG: But im too scared of ghosts to go inside the mansion."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"L: I guess I should break it to you then buddy."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: No, I''m sorry but I''m not a ghost. I am an aberration."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"H: We can help by tuning the water back on for you."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"L: Yea, hand over the water wheel and a token and we will turn it on."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: I’ll give you the water wheel but I don’t have a token, Bunchin took it."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"L: Who’s Bunchin?"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: He’s the new grounds keeper, he thinks watering the flowers is a waste."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: But I know this flower is special and it needs just one more watering before it blooms."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"(Activate the water line somewhere in the castle)"},{"type":"hardBreak"},{"type":"text","text":"H: There we go flicks, now you have plenty of water."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"FG: I watch over the flowers now in the castle yard, since Bunchin ran away."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"FG: I was right, this flower finally bloomed, here take this mysterious wooden thing that came out of it."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"L: Appreciate you Flicks, ok now how much more do we need to find?"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"H: Quite a lot Lyre, so lets move."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Bunchin: Dialogue (Found in lumbermill)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, B = Bunchin"}]},{"type":"paragraph","content":[{"type":"text","text":"B: Oh boy am I crazy, the name’s Bunchin chums, who might you be, hoo wee!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: I’m Harper what is the deal with you buddy?"}]},{"type":"paragraph","content":[{"type":"text","text":"B: I’m gonna bite you in the legs, but wait, just a moment."}]},{"type":"paragraph","content":[{"type":"text","text":"L: Uhhh, my name’s… Lyre, are you some kind of whacko?"}]},{"type":"paragraph","content":[{"type":"text","text":"B: No sir no sir no sir!!! My machine’s stopped workin, gotta cut the logs for the man in the city you see. Figure out how to solve my issue, or I just can’t give you this token I found in the woods earlier!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: We’ll try to find something for you, let''s go Lyre."}]},{"type":"paragraph","content":[{"type":"text","text":"L: “I’d leave this weirdo alone if you ask me”. (whisper)"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"(The two activate a switch outside guarded by ghosts)"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Alright, those guys sure scared us, but we’ve started up your machine again Bunchin."}]},{"type":"paragraph","content":[{"type":"text","text":"L: Hand over that token you promised, don’t chicken out!"}]},{"type":"paragraph","content":[{"type":"text","text":"B: Creepy wacky friends! Take a token, take it, take it!"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Sticks and Mips: Dialogue (Found on a tree together)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, S = Sticks, M = Mips"}]},{"type":"paragraph","content":[{"type":"text","text":"S: We are cats you see, my name’s Sticks."}]},{"type":"paragraph","content":[{"type":"text","text":"M: My name’s Mips, a curious little one!"}]},{"type":"paragraph","content":[{"type":"text","text":"S: We are Sticks and Mips, the cat duo!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: You would think the two of you would rhyme at least, being a duo and all."}]},{"type":"paragraph","content":[{"type":"text","text":"L: What’s wrong, cat got your tongue?"}]},{"type":"paragraph","content":[{"type":"text","text":"S: I do not get the joke, you two must find a way to reach the top tree branch!"}]},{"type":"paragraph","content":[{"type":"text","text":"M: Yes, the top branch will earn our respect, if you can’t then no reward for you!"}]},{"type":"paragraph","content":[{"type":"text","text":"L: Ok, but how are we supposed to do that?"}]},{"type":"paragraph","content":[{"type":"text","text":"H: The top of the tree is too high for us, but I suppose we can try and find a way."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Mrs. Crow: Dialogue (Found ???)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, C = mrs. crow"}]},{"type":"paragraph","content":[{"type":"text","text":"C: Oh boo hoo, can’t anybody out there help me with my problem!"}]},{"type":"paragraph","content":[{"type":"text","text":"L: That depends, is the reward in it for us?"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Lyre! That’s no way to talk to someone in need, now tell us what your issue is."}]},{"type":"paragraph","content":[{"type":"text","text":"C: Well… the name’s Mrs. Crow and I just can’t find my husband anywhere!"}]},{"type":"paragraph","content":[{"type":"text","text":"L: “I don’t think I should tell her what happened…” (whispers)"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Where was the last place that you found them?"}]},{"type":"paragraph","content":[{"type":"text","text":"C: He… was set up to guard the eggs in the nest, but I just don’t know where he is now! Boo hoo hoo!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Alright alright, we’ll look for him."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"(Mr. crow can be found trapped under rubble in Firestone mountain, can be broken with a ground pound, the two talk in Firestone mountain)"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"H: We found him and brought him home to you, is there anything else you needed?"}]},{"type":"paragraph","content":[{"type":"text","text":"L: Oh no not another task…"}]},{"type":"paragraph","content":[{"type":"text","text":"C: No… Thank you so much for finding him, take this token that I had all along."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Kreakli Rhymes"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"While spooky spectres keep you at bay,"}]},{"type":"paragraph","content":[{"type":"text","text":"maybe I can finish my spell today!"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Halls like a labyrinth, floors made of wood,"}]},{"type":"paragraph","content":[{"type":"text","text":"get out of my mansion, you really should."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Have you had a chance to meet the ghosts inside,"}]},{"type":"paragraph","content":[{"type":"text","text":"you aren''t meant to be here, I thought I clarified."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"H&L Key Locations on Island"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"3 Mist-side Castle;"}]},{"type":"paragraph","content":[{"type":"text","text":"-Graveyard (1)"}]},{"type":"paragraph","content":[{"type":"text","text":"-Mist-side Manor (2)"}]},{"type":"paragraph","content":[{"type":"text","text":"-Murky Walkways (3)"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Fixed Sabercat hat texture on eye"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Mansion Layout"}]},{"type":"paragraph","content":[{"type":"text","text":"The main mansion is made up of four different layers, each containing keys to allow the player to complete the castle."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"The castle starts the player off in the main entrance. Once the player picks up the key, they can take it to the first door. After unlocking the [Entrance Door], players will be able to continue into the castle by walking down to the end of the hallway ahead. Players will pick up and use the [Kitchen Key] on the [Kitchen] Door which unlocks the [Kitchen]."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Inside the [Kitchen] players will proceed to grab the [Star room key] located within the [Fridge]. Players unlock the Fridge by pulling the lever closest to the door, after players are outside the kitchen, within the closet closest to the kitchen is another lever which shuts off the valve system for the [Fridge]."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"After walking into the fridge players can collect the [Star Room Key] and unlock the [Star Room]. Once players have unlocked the [Star room], they must use  [Ledge Climb/Hang] to get across the room ledge to obtain the [Sewing Room Key]. "},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"The player now must press the button next to the Sewing Room Key to have the platforms pop out of the wall and run across them quickly as they will retract back into the wall. Once they reach the Sewing Room, they can walk inside and either pull the lever revealing the door location that is cracked. Or the player can roll/attack/air kick the door down and avoid using the lever for the door light."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Players will obtain the [Diamond Key] which will be used to unlock the next floor up. After walking upstairs to the second floor, players will walk into the closet next to the Library and collect the [Spade Key]. After walking back downstairs to the first floor players can then use the Spade Key on the Spade door unlocking the [Basement]. "},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Once inside the [Basement] players will go into the [Boiler room] to turn on the water systems, allowing them to collect the twisted token inside the fire. Players then must turn off the electricity in the boiler room by transforming into a mouse and breaking the machine from the inside by pressing a button. Then the player can go grab the key behind the exposed electric wires. After players grab the library key, they can unlock the [Library]."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"After entering the library the player can break the panel on the wall to find an elevator allowing them to go to the [Basement] into the blocked room. There the player will find the movie room key. They can take the key back up to the library. After they have the Key to the [Movie Room] the player must climb the stack of books near the room entrance and walk along the vents. After the player gets to the top of the library, they must break the rusty fence in the wall in the back corner. Once the player has walked through the vent shaft they can shell shoot the button on the wall opening the book shelf back up for the [Library]. The player will then either go get the movie room key if not already gone and gotten it, and take it to the door of the [Movie Room]."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Players walk to the end of the hallway and press the button pushing the shelf to the side. Inside the room they have to find the lever hidden behind the movie image screen. Pulling the lever will open the back exit of the [Movie Room]. They must collect the Letter Room Key and unlock the [Letter Room]. Inside the letter room is a puzzle consisting of 4 paintings. All 4 paintings are different, and the player must step on the buttons Starting with Gold, Silver, Platinum, and then Bronze. Once the player has pressed all pressure plates down in this order then the door will open exposing the [Storage Room] Key. "},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"After players unlock the storage room, they must go into the right side of the storage room and shoot a shell at the button behind them as soon as they walk into the room. Bricks and a button will shoot out for about 15 seconds. After 15 seconds, the bridge retracts, and players must hit the shell button a second time. If the player gets across the bridge into the secret room, then they hit the button that opens the elevator allowing them to go to the kitchen storage room. Once inside the Kitchen storage room, players can get on top of the kitchen shelves by jumping on the first cabinet and then the shelf, lastly to the top. Players grab the Heart key giving them access to the final floor which is floor 3."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Players go to the right and grab the observatory key past the door, they bring it to the observatory Door and unlock it. They do a puzzle in the observatory which gives them the key to the green house room. Players grab the green house key and take it through the hole in the top of the observatory side room with a large root guiding them up to it. Players walk through and use the key on the Green house room once they find it. After players unlock the green house room,"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Story board here- Nothing decided for the green house room. Only parkour but i need it to be walking only so we gotta figure it out."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Basement"}]},{"type":"paragraph","content":[{"type":"text","text":"The basement contains the power systems,  wash room, exercise room, and boss room."}]},{"type":"paragraph","content":[{"type":"text","text":"Floor 1"}]},{"type":"paragraph","content":[{"type":"text","text":"The first floor has the kitchen, star room, sewing room, and path up and down a floor."}]},{"type":"paragraph"},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Floor 2"}]},{"type":"paragraph","content":[{"type":"text","text":"The second floor has the library, movie, painting, storage, and path up and down."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Floor 3"}]},{"type":"paragraph","content":[{"type":"text","text":"The third floor has the observatory, green house room, and path downstairs."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Headless Horseman Boss"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Headless Horseman Boss: Dialogue"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, Horseman = HM, Horsey = HE"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Whoa who is that?"}]},{"type":"paragraph","content":[{"type":"text","text":"L: This guy looks scary, maybe we should leave."}]},{"type":"paragraph","content":[{"type":"text","text":"HH: Leave? But you just got here! Why don;t we have some fun?!"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Bring cat a tuna from deep dank waters"}]},{"type":"paragraph","content":[{"type":"text","text":"Schwoomy"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Current Stats"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Baddies: Eagle Warrior, Tribes-man, Tak-tak"}]},{"type":"paragraph","content":[{"type":"text","text":"Level Collectables"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Standard"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Notes (200 / 200)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Buggies (5 / 5)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Cash (3 / 3)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Gold (3 / 3)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Pages (3 / 3)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Panda Coins (2 / 2)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Pixies (3 / 3)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Pocus Tokens (10 / 10)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Twisted Token (20 / 20)"}]}]}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Unique"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]}]}','Dragonfirebane','2026-08-03 18:10:52');
INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(137,17,'{"type":"doc","content":[{"type":"paragraph"}]}','Dragonfirebane','2026-08-03 18:12:16');
INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(138,3,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mist-Side Castle"}]},{"type":"paragraph","content":[{"type":"text","text":"Spooky shadows roam the halls of the castle, while undead dwellers walk the grounds outside."}]},{"type":"paragraph","content":[{"type":"text","text":"Friendlies: Flicks the ghost (water fountain ghost)"}]},{"type":"paragraph","content":[{"type":"text","text":"Baddies: Dweller (zombie), Ghosti, Skish (skeleton fish), Haunted statue, Shadehand"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Chewy: Dialogue (Found in misty woods)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, C = Chewy"}]},{"type":"paragraph","content":[{"type":"text","text":"C: The names Chewy, and who are you? Why don’t you look like a zombie?"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"H: You aren’t chasing us down either, but you sure look like an enemy."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"C: I left my town because even the zombies found me creepy and stayed away."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"C: Now I hide in these woods looking for some tasty crows. Do you know where I can find some crow eggs?"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"H: No I’m afraid not Chewy, anything else we could help you with?"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"C: Well if you could manage to clear the zombies from my home, I would give you this token I found from a crow I caught earlier."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"L: I guess we’ll see what we can do about your problem…"}]},{"type":"paragraph","content":[{"type":"text","text":"(Clear the zombies from chewy’s home once)"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"L: Alright you weirdo, we did some house cleaning for you, hand over the token now."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"C: Woohoo, thanks for taking care of me guys, now as promised."}]},{"type":"paragraph","content":[{"type":"text","text":"(Chewy starts to run away)"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"C: My house has the best view of the crows nest, thanks Harper and Lyre!"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Flicks the Ghost: Dialogue (Found in graveyard by fountain)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, FG = Flicks the ghost"}]},{"type":"paragraph","content":[{"type":"text","text":"FG: My name is Flicks, and  I’m so sad now that all of my fountain water’s gone!"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"L: What do you need water for, you’re just a ghost!"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"H: Lyre, that’s no way to talk to our new friend. Is there some way to run water to your fountain?"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: Yes but you need to get inside the mansion to turn it on. I have the water wheel you need."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"FG: But im too scared of ghosts to go inside the mansion."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"L: I guess I should break it to you then buddy."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: No, I''m sorry but I''m not a ghost. I am an aberration."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"H: We can help by tuning the water back on for you."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"L: Yea, hand over the water wheel and a token and we will turn it on."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: I’ll give you the water wheel but I don’t have a token, Bunchin took it."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"L: Who’s Bunchin?"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: He’s the new grounds keeper, he thinks watering the flowers is a waste."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: But I know this flower is special and it needs just one more watering before it blooms."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"(Activate the water line somewhere in the castle)"},{"type":"hardBreak"},{"type":"text","text":"H: There we go flicks, now you have plenty of water."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"FG: I watch over the flowers now in the castle yard, since Bunchin ran away."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"FG: I was right, this flower finally bloomed, here take this mysterious wooden thing that came out of it."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"L: Appreciate you Flicks, ok now how much more do we need to find?"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"H: Quite a lot Lyre, so lets move."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Bunchin: Dialogue (Found in lumbermill)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, B = Bunchin"}]},{"type":"paragraph","content":[{"type":"text","text":"B: Oh boy am I crazy, the name’s Bunchin chums, who might you be, hoo wee!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: I’m Harper what is the deal with you buddy?"}]},{"type":"paragraph","content":[{"type":"text","text":"B: I’m gonna bite you in the legs, but wait, just a moment."}]},{"type":"paragraph","content":[{"type":"text","text":"L: Uhhh, my name’s… Lyre, are you some kind of whacko?"}]},{"type":"paragraph","content":[{"type":"text","text":"B: No sir no sir no sir!!! My machine’s stopped workin, gotta cut the logs for the man in the city you see. Figure out how to solve my issue, or I just can’t give you this token I found in the woods earlier!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: We’ll try to find something for you, let''s go Lyre."}]},{"type":"paragraph","content":[{"type":"text","text":"L: “I’d leave this weirdo alone if you ask me”. (whisper)"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"(The two activate a switch outside guarded by ghosts)"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Alright, those guys sure scared us, but we’ve started up your machine again Bunchin."}]},{"type":"paragraph","content":[{"type":"text","text":"L: Hand over that token you promised, don’t chicken out!"}]},{"type":"paragraph","content":[{"type":"text","text":"B: Creepy wacky friends! Take a token, take it, take it!"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Sticks and Mips: Dialogue (Found on a tree together)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, S = Sticks, M = Mips"}]},{"type":"paragraph","content":[{"type":"text","text":"S: We are cats you see, my name’s Sticks."}]},{"type":"paragraph","content":[{"type":"text","text":"M: My name’s Mips, a curious little one!"}]},{"type":"paragraph","content":[{"type":"text","text":"S: We are Sticks and Mips, the cat duo!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: You would think the two of you would rhyme at least, being a duo and all."}]},{"type":"paragraph","content":[{"type":"text","text":"L: What’s wrong, cat got your tongue?"}]},{"type":"paragraph","content":[{"type":"text","text":"S: I do not get the joke, you two must find a way to reach the top tree branch!"}]},{"type":"paragraph","content":[{"type":"text","text":"M: Yes, the top branch will earn our respect, if you can’t then no reward for you!"}]},{"type":"paragraph","content":[{"type":"text","text":"L: Ok, but how are we supposed to do that?"}]},{"type":"paragraph","content":[{"type":"text","text":"H: The top of the tree is too high for us, but I suppose we can try and find a way."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Mrs. Crow: Dialogue (Found ???)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, C = mrs. crow"}]},{"type":"paragraph","content":[{"type":"text","text":"C: Oh boo hoo, can’t anybody out there help me with my problem!"}]},{"type":"paragraph","content":[{"type":"text","text":"L: That depends, is the reward in it for us?"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Lyre! That’s no way to talk to someone in need, now tell us what your issue is."}]},{"type":"paragraph","content":[{"type":"text","text":"C: Well… the name’s Mrs. Crow and I just can’t find my husband anywhere!"}]},{"type":"paragraph","content":[{"type":"text","text":"L: “I don’t think I should tell her what happened…” (whispers)"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Where was the last place that you found them?"}]},{"type":"paragraph","content":[{"type":"text","text":"C: He… was set up to guard the eggs in the nest, but I just don’t know where he is now! Boo hoo hoo!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Alright alright, we’ll look for him."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"(Mr. crow can be found trapped under rubble in Firestone mountain, can be broken with a ground pound, the two talk in Firestone mountain)"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"H: We found him and brought him home to you, is there anything else you needed?"}]},{"type":"paragraph","content":[{"type":"text","text":"L: Oh no not another task…"}]},{"type":"paragraph","content":[{"type":"text","text":"C: No… Thank you so much for finding him, take this token that I had all along."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Kreakli Rhymes"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"While spooky spectres keep you at bay,"}]},{"type":"paragraph","content":[{"type":"text","text":"maybe I can finish my spell today!"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Halls like a labyrinth, floors made of wood,"}]},{"type":"paragraph","content":[{"type":"text","text":"get out of my mansion, you really should."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Have you had a chance to meet the ghosts inside,"}]},{"type":"paragraph","content":[{"type":"text","text":"you aren''t meant to be here, I thought I clarified."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"H&L Key Locations on Island"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"3 Mist-side Castle;"}]},{"type":"paragraph","content":[{"type":"text","text":"-Graveyard (1)"}]},{"type":"paragraph","content":[{"type":"text","text":"-Mist-side Manor (2)"}]},{"type":"paragraph","content":[{"type":"text","text":"-Murky Walkways (3)"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Fixed Sabercat hat texture on eye"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Mansion Layout"}]},{"type":"paragraph","content":[{"type":"text","text":"The main mansion is made up of four different layers, each containing keys to allow the player to complete the castle."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"The castle starts the player off in the main entrance. Once the player picks up the key, they can take it to the first door. After unlocking the [Entrance Door], players will be able to continue into the castle by walking down to the end of the hallway ahead. Players will pick up and use the [Kitchen Key] on the [Kitchen] Door which unlocks the [Kitchen]."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Inside the [Kitchen] players will proceed to grab the [Star room key] located within the [Fridge]. Players unlock the Fridge by pulling the lever closest to the door, after players are outside the kitchen, within the closet closest to the kitchen is another lever which shuts off the valve system for the [Fridge]."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"After walking into the fridge players can collect the [Star Room Key] and unlock the [Star Room]. Once players have unlocked the [Star room], they must use  [Ledge Climb/Hang] to get across the room ledge to obtain the [Sewing Room Key]. "},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"The player now must press the button next to the Sewing Room Key to have the platforms pop out of the wall and run across them quickly as they will retract back into the wall. Once they reach the Sewing Room, they can walk inside and either pull the lever revealing the door location that is cracked. Or the player can roll/attack/air kick the door down and avoid using the lever for the door light."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Players will obtain the [Diamond Key] which will be used to unlock the next floor up. After walking upstairs to the second floor, players will walk into the closet next to the Library and collect the [Spade Key]. After walking back downstairs to the first floor players can then use the Spade Key on the Spade door unlocking the [Basement]. "},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Once inside the [Basement] players will go into the [Boiler room] to turn on the water systems, allowing them to collect the twisted token inside the fire. Players then must turn off the electricity in the boiler room by transforming into a mouse and breaking the machine from the inside by pressing a button. Then the player can go grab the key behind the exposed electric wires. After players grab the library key, they can unlock the [Library]."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"After entering the library the player can break the panel on the wall to find an elevator allowing them to go to the [Basement] into the blocked room. There the player will find the movie room key. They can take the key back up to the library. After they have the Key to the [Movie Room] the player must climb the stack of books near the room entrance and walk along the vents. After the player gets to the top of the library, they must break the rusty fence in the wall in the back corner. Once the player has walked through the vent shaft they can shell shoot the button on the wall opening the book shelf back up for the [Library]. The player will then either go get the movie room key if not already gone and gotten it, and take it to the door of the [Movie Room]."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Players walk to the end of the hallway and press the button pushing the shelf to the side. Inside the room they have to find the lever hidden behind the movie image screen. Pulling the lever will open the back exit of the [Movie Room]. They must collect the Letter Room Key and unlock the [Letter Room]. Inside the letter room is a puzzle consisting of 4 paintings. All 4 paintings are different, and the player must step on the buttons Starting with Gold, Silver, Platinum, and then Bronze. Once the player has pressed all pressure plates down in this order then the door will open exposing the [Storage Room] Key. "},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"After players unlock the storage room, they must go into the right side of the storage room and shoot a shell at the button behind them as soon as they walk into the room. Bricks and a button will shoot out for about 15 seconds. After 15 seconds, the bridge retracts, and players must hit the shell button a second time. If the player gets across the bridge into the secret room, then they hit the button that opens the elevator allowing them to go to the kitchen storage room. Once inside the Kitchen storage room, players can get on top of the kitchen shelves by jumping on the first cabinet and then the shelf, lastly to the top. Players grab the Heart key giving them access to the final floor which is floor 3."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Players go to the right and grab the observatory key past the door, they bring it to the observatory Door and unlock it. They do a puzzle in the observatory which gives them the key to the green house room. Players grab the green house key and take it through the hole in the top of the observatory side room with a large root guiding them up to it. Players walk through and use the key on the Green house room once they find it. After players unlock the green house room,"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Story board here- Nothing decided for the green house room. Only parkour but i need it to be walking only so we gotta figure it out."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Basement"}]},{"type":"paragraph","content":[{"type":"text","text":"The basement contains the power systems,  wash room, exercise room, and boss room."}]},{"type":"paragraph","content":[{"type":"text","text":"Floor 1"}]},{"type":"paragraph","content":[{"type":"text","text":"The first floor has the kitchen, star room, sewing room, and path up and down a floor."}]},{"type":"paragraph"},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Floor 2"}]},{"type":"paragraph","content":[{"type":"text","text":"The second floor has the library, movie, painting, storage, and path up and down."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Floor 3"}]},{"type":"paragraph","content":[{"type":"text","text":"The third floor has the observatory, green house room, and path downstairs."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Headless Horseman Boss"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Headless Horseman Boss: Dialogue"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, Horseman = HM, Horsey = HE"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Whoa who is that?"}]},{"type":"paragraph","content":[{"type":"text","text":"L: This guy looks scary, maybe we should leave."}]},{"type":"paragraph","content":[{"type":"text","text":"HH: Leave? But you just got here! Why don;t we have some fun?!"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Bring cat a tuna from deep dank waters"}]},{"type":"paragraph","content":[{"type":"text","text":"Schwoomy"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Current Stats"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Baddies: Eagle Warrior, Tribes-man, Tak-tak"}]},{"type":"paragraph","content":[{"type":"text","text":"Level Collectables"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Standard"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Notes (200 / 200)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Buggies (5 / 5)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Cash (3 / 3)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Gold (3 / 3)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Pages (3 / 3)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Panda Coins (2 / 2)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Pixies (3 / 3)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Pocus Tokens (10 / 10)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Twisted Token (20 / 20)"}]}]}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Unique"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]}]}','Dragonfirebane','2026-08-03 18:12:46');
INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(139,16,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Chewy is located inside Mistside Castle. He wants the player to clear his house of all the creepy zombies otherwise known as Dwellers."}]}]}','Dragonfirebane','2026-08-03 18:12:54');
INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(140,3,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mist-Side Castle"}]},{"type":"paragraph","content":[{"type":"text","text":"Spooky shadows roam the halls of the castle, while undead dwellers walk the grounds outside."}]},{"type":"paragraph","content":[{"type":"text","text":"Friendlies: Flicks the ghost (water fountain ghost)"}]},{"type":"paragraph","content":[{"type":"text","text":"Baddies: Dweller (zombie), Ghosti, Skish (skeleton fish), Haunted statue, Shadehand"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Flicks the Ghost: Dialogue (Found in graveyard by fountain)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, FG = Flicks the ghost"}]},{"type":"paragraph","content":[{"type":"text","text":"FG: My name is Flicks, and  I’m so sad now that all of my fountain water’s gone!"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"L: What do you need water for, you’re just a ghost!"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"H: Lyre, that’s no way to talk to our new friend. Is there some way to run water to your fountain?"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: Yes but you need to get inside the mansion to turn it on. I have the water wheel you need."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"FG: But im too scared of ghosts to go inside the mansion."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"L: I guess I should break it to you then buddy."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: No, I''m sorry but I''m not a ghost. I am an aberration."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"H: We can help by tuning the water back on for you."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"L: Yea, hand over the water wheel and a token and we will turn it on."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: I’ll give you the water wheel but I don’t have a token, Bunchin took it."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"L: Who’s Bunchin?"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: He’s the new grounds keeper, he thinks watering the flowers is a waste."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: But I know this flower is special and it needs just one more watering before it blooms."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"(Activate the water line somewhere in the castle)"},{"type":"hardBreak"},{"type":"text","text":"H: There we go flicks, now you have plenty of water."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"FG: I watch over the flowers now in the castle yard, since Bunchin ran away."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"FG: I was right, this flower finally bloomed, here take this mysterious wooden thing that came out of it."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"L: Appreciate you Flicks, ok now how much more do we need to find?"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"H: Quite a lot Lyre, so lets move."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Bunchin: Dialogue (Found in lumbermill)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, B = Bunchin"}]},{"type":"paragraph","content":[{"type":"text","text":"B: Oh boy am I crazy, the name’s Bunchin chums, who might you be, hoo wee!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: I’m Harper what is the deal with you buddy?"}]},{"type":"paragraph","content":[{"type":"text","text":"B: I’m gonna bite you in the legs, but wait, just a moment."}]},{"type":"paragraph","content":[{"type":"text","text":"L: Uhhh, my name’s… Lyre, are you some kind of whacko?"}]},{"type":"paragraph","content":[{"type":"text","text":"B: No sir no sir no sir!!! My machine’s stopped workin, gotta cut the logs for the man in the city you see. Figure out how to solve my issue, or I just can’t give you this token I found in the woods earlier!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: We’ll try to find something for you, let''s go Lyre."}]},{"type":"paragraph","content":[{"type":"text","text":"L: “I’d leave this weirdo alone if you ask me”. (whisper)"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"(The two activate a switch outside guarded by ghosts)"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Alright, those guys sure scared us, but we’ve started up your machine again Bunchin."}]},{"type":"paragraph","content":[{"type":"text","text":"L: Hand over that token you promised, don’t chicken out!"}]},{"type":"paragraph","content":[{"type":"text","text":"B: Creepy wacky friends! Take a token, take it, take it!"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Sticks and Mips: Dialogue (Found on a tree together)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, S = Sticks, M = Mips"}]},{"type":"paragraph","content":[{"type":"text","text":"S: We are cats you see, my name’s Sticks."}]},{"type":"paragraph","content":[{"type":"text","text":"M: My name’s Mips, a curious little one!"}]},{"type":"paragraph","content":[{"type":"text","text":"S: We are Sticks and Mips, the cat duo!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: You would think the two of you would rhyme at least, being a duo and all."}]},{"type":"paragraph","content":[{"type":"text","text":"L: What’s wrong, cat got your tongue?"}]},{"type":"paragraph","content":[{"type":"text","text":"S: I do not get the joke, you two must find a way to reach the top tree branch!"}]},{"type":"paragraph","content":[{"type":"text","text":"M: Yes, the top branch will earn our respect, if you can’t then no reward for you!"}]},{"type":"paragraph","content":[{"type":"text","text":"L: Ok, but how are we supposed to do that?"}]},{"type":"paragraph","content":[{"type":"text","text":"H: The top of the tree is too high for us, but I suppose we can try and find a way."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Mrs. Crow: Dialogue (Found ???)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, C = mrs. crow"}]},{"type":"paragraph","content":[{"type":"text","text":"C: Oh boo hoo, can’t anybody out there help me with my problem!"}]},{"type":"paragraph","content":[{"type":"text","text":"L: That depends, is the reward in it for us?"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Lyre! That’s no way to talk to someone in need, now tell us what your issue is."}]},{"type":"paragraph","content":[{"type":"text","text":"C: Well… the name’s Mrs. Crow and I just can’t find my husband anywhere!"}]},{"type":"paragraph","content":[{"type":"text","text":"L: “I don’t think I should tell her what happened…” (whispers)"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Where was the last place that you found them?"}]},{"type":"paragraph","content":[{"type":"text","text":"C: He… was set up to guard the eggs in the nest, but I just don’t know where he is now! Boo hoo hoo!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Alright alright, we’ll look for him."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"(Mr. crow can be found trapped under rubble in Firestone mountain, can be broken with a ground pound, the two talk in Firestone mountain)"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"H: We found him and brought him home to you, is there anything else you needed?"}]},{"type":"paragraph","content":[{"type":"text","text":"L: Oh no not another task…"}]},{"type":"paragraph","content":[{"type":"text","text":"C: No… Thank you so much for finding him, take this token that I had all along."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Kreakli Rhymes"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"While spooky spectres keep you at bay,"}]},{"type":"paragraph","content":[{"type":"text","text":"maybe I can finish my spell today!"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Halls like a labyrinth, floors made of wood,"}]},{"type":"paragraph","content":[{"type":"text","text":"get out of my mansion, you really should."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Have you had a chance to meet the ghosts inside,"}]},{"type":"paragraph","content":[{"type":"text","text":"you aren''t meant to be here, I thought I clarified."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"H&L Key Locations on Island"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"3 Mist-side Castle;"}]},{"type":"paragraph","content":[{"type":"text","text":"-Graveyard (1)"}]},{"type":"paragraph","content":[{"type":"text","text":"-Mist-side Manor (2)"}]},{"type":"paragraph","content":[{"type":"text","text":"-Murky Walkways (3)"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Fixed Sabercat hat texture on eye"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Mansion Layout"}]},{"type":"paragraph","content":[{"type":"text","text":"The main mansion is made up of four different layers, each containing keys to allow the player to complete the castle."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"The castle starts the player off in the main entrance. Once the player picks up the key, they can take it to the first door. After unlocking the [Entrance Door], players will be able to continue into the castle by walking down to the end of the hallway ahead. Players will pick up and use the [Kitchen Key] on the [Kitchen] Door which unlocks the [Kitchen]."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Inside the [Kitchen] players will proceed to grab the [Star room key] located within the [Fridge]. Players unlock the Fridge by pulling the lever closest to the door, after players are outside the kitchen, within the closet closest to the kitchen is another lever which shuts off the valve system for the [Fridge]."},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"After walking into the fridge players can collect the [Star Room Key] and unlock the [Star Room]. Once players have unlocked the [Star room], they must use  [Ledge Climb/Hang] to get across the room ledge to obtain the [Sewing Room Key]. "},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"The player now must press the button next to the Sewing Room Key to have the platforms pop out of the wall and run across them quickly as they will retract back into the wall. Once they reach the Sewing Room, they can walk inside and either pull the lever revealing the door location that is cracked. Or the player can roll/attack/air kick the door down and avoid using the lever for the door light."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Players will obtain the [Diamond Key] which will be used to unlock the next floor up. After walking upstairs to the second floor, players will walk into the closet next to the Library and collect the [Spade Key]. After walking back downstairs to the first floor players can then use the Spade Key on the Spade door unlocking the [Basement]. "},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Once inside the [Basement] players will go into the [Boiler room] to turn on the water systems, allowing them to collect the twisted token inside the fire. Players then must turn off the electricity in the boiler room by transforming into a mouse and breaking the machine from the inside by pressing a button. Then the player can go grab the key behind the exposed electric wires. After players grab the library key, they can unlock the [Library]."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"After entering the library the player can break the panel on the wall to find an elevator allowing them to go to the [Basement] into the blocked room. There the player will find the movie room key. They can take the key back up to the library. After they have the Key to the [Movie Room] the player must climb the stack of books near the room entrance and walk along the vents. After the player gets to the top of the library, they must break the rusty fence in the wall in the back corner. Once the player has walked through the vent shaft they can shell shoot the button on the wall opening the book shelf back up for the [Library]. The player will then either go get the movie room key if not already gone and gotten it, and take it to the door of the [Movie Room]."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Players walk to the end of the hallway and press the button pushing the shelf to the side. Inside the room they have to find the lever hidden behind the movie image screen. Pulling the lever will open the back exit of the [Movie Room]. They must collect the Letter Room Key and unlock the [Letter Room]. Inside the letter room is a puzzle consisting of 4 paintings. All 4 paintings are different, and the player must step on the buttons Starting with Gold, Silver, Platinum, and then Bronze. Once the player has pressed all pressure plates down in this order then the door will open exposing the [Storage Room] Key. "},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"After players unlock the storage room, they must go into the right side of the storage room and shoot a shell at the button behind them as soon as they walk into the room. Bricks and a button will shoot out for about 15 seconds. After 15 seconds, the bridge retracts, and players must hit the shell button a second time. If the player gets across the bridge into the secret room, then they hit the button that opens the elevator allowing them to go to the kitchen storage room. Once inside the Kitchen storage room, players can get on top of the kitchen shelves by jumping on the first cabinet and then the shelf, lastly to the top. Players grab the Heart key giving them access to the final floor which is floor 3."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Players go to the right and grab the observatory key past the door, they bring it to the observatory Door and unlock it. They do a puzzle in the observatory which gives them the key to the green house room. Players grab the green house key and take it through the hole in the top of the observatory side room with a large root guiding them up to it. Players walk through and use the key on the Green house room once they find it. After players unlock the green house room,"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Story board here- Nothing decided for the green house room. Only parkour but i need it to be walking only so we gotta figure it out."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Basement"}]},{"type":"paragraph","content":[{"type":"text","text":"The basement contains the power systems,  wash room, exercise room, and boss room."}]},{"type":"paragraph","content":[{"type":"text","text":"Floor 1"}]},{"type":"paragraph","content":[{"type":"text","text":"The first floor has the kitchen, star room, sewing room, and path up and down a floor."}]},{"type":"paragraph"},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Floor 2"}]},{"type":"paragraph","content":[{"type":"text","text":"The second floor has the library, movie, painting, storage, and path up and down."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"Floor 3"}]},{"type":"paragraph","content":[{"type":"text","text":"The third floor has the observatory, green house room, and path downstairs."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Headless Horseman Boss"}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Headless Horseman Boss: Dialogue"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, Horseman = HM, Horsey = HE"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Whoa who is that?"}]},{"type":"paragraph","content":[{"type":"text","text":"L: This guy looks scary, maybe we should leave."}]},{"type":"paragraph","content":[{"type":"text","text":"HH: Leave? But you just got here! Why don;t we have some fun?!"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Bring cat a tuna from deep dank waters"}]},{"type":"paragraph","content":[{"type":"text","text":"Schwoomy"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Current Stats"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Baddies: Eagle Warrior, Tribes-man, Tak-tak"}]},{"type":"paragraph","content":[{"type":"text","text":"Level Collectables"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Standard"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Notes (200 / 200)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Buggies (5 / 5)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Cash (3 / 3)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Gold (3 / 3)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Pages (3 / 3)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Panda Coins (2 / 2)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Pixies (3 / 3)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Pocus Tokens (10 / 10)"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","marks":[{"type":"strike"}],"text":"Twisted Token (20 / 20)"}]}]}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","marks":[{"type":"bold"}],"text":"Unique"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]}]}','Dragonfirebane','2026-08-03 18:13:14');
INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(141,19,'{"type":"doc","content":[{"type":"paragraph"}]}','Dragonfirebane','2026-08-03 18:15:42');
INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(142,19,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Flicks the Ghost is located inside Mistside Castle near the fountain"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Flicks the Ghost: Dialogue"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, FG = Flicks the ghost"}]},{"type":"paragraph","content":[{"type":"text","text":"FG: My name is Flicks, and  I’m so sad now that all of my fountain water’s gone!"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"L: What do you need water for, you’re just a ghost!"}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"H: Lyre, that’s no way to talk to our new friend. Is there some way to run water to your fountain?"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: Yes but you need to get inside the mansion to turn it on. I have the water wheel you need."},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"FG: But im too scared of ghosts to go inside the mansion."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"L: I guess I should break it to you then buddy."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: No, I''m sorry but I''m not a ghost. I am an aberration."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"H: We can help by tuning the water back on for you."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"L: Yea, hand over the water wheel and a token and we will turn it on."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: I’ll give you the water wheel but I don’t have a token, Bunchin took it."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"L: Who’s Bunchin?"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: He’s the new grounds keeper, he thinks watering the flowers is a waste."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"FG: But I know this flower is special and it needs just one more watering before it blooms."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"(Activate the water line somewhere in the castle)"},{"type":"hardBreak"},{"type":"text","text":"H: There we go flicks, now you have plenty of water."}]},{"type":"paragraph"},{"type":"paragraph","content":[{"type":"text","text":"FG: I watch over the flowers now in the castle yard, since Bunchin ran away."},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"FG: I was right, this flower finally bloomed, here take this mysterious wooden thing that came out of it."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"text","text":"L: Appreciate you Flicks, ok now how much more do we need to find?"},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"H: Quite a lot Lyre, so lets move."}]},{"type":"paragraph"}]}','Dragonfirebane','2026-08-03 18:16:08');
INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(143,3,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mist-Side Castle"}]},{"type":"paragraph","content":[{"type":"text","text":"Spooky shadows roam the halls of the castle, while undead dwellers walk the grounds outside."}]},{"type":"paragraph","content":[{"type":"text","text":"Friendlies: Flicks the ghost (water fountain ghost)"}]},{"type":"paragraph","content":[{"type":"text","text":"Baddies: Dweller (zombie), Ghosti, Skish (skeleton fish), Haunted statue, Shadehand"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Bunchin: Dialogue (Found in lumbermill)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, B = Bunchin"}]},{"type":"paragraph","content":[{"type":"text","text":"B: Oh boy am I crazy, the name’s Bunchin chums, who might you be, hoo wee!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: I’m Harper what is the deal with you buddy?"}]},{"type":"paragraph","content":[{"type":"text","text":"B: I’m gonna bite you in the legs, but wait, just a moment."}]},{"type":"paragraph","content":[{"type":"text","text":"L: Uhhh, my name’s… Lyre, are you some kind of whacko?"}]},{"type":"paragraph","content":[{"type":"text","text":"B: No sir no sir no sir!!! My machine’s stopped workin, gotta cut the logs for the man in the city you see. Figure out how to solve my issue, or I just can’t give you this token I found in the woods earlier!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: We’ll try to find something for you, let''s go Lyre."}]},{"type":"paragraph","content":[{"type":"text","text":"L: “I’d leave this weirdo alone if you ask me”. (whisper)"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"(The two activate a switch outside guarded by ghosts)"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Alright, those guys sure scared us, but we’ve started up your machine again Bunchin."}]},{"type":"paragraph","content":[{"type":"text","text":"L: Hand over that token you promised, don’t chicken out!"}]},{"type":"paragraph","content":[{"type":"text","text":"B: Creepy wacky friends! Take a token, take it, take it!"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Sticks and Mips: Dialogue (Found on a tree together)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, S = Sticks, M = Mips"}]},{"type":"paragraph","content":[{"type":"text","text":"S: We are cats you see, my name’s Sticks."}]},{"type":"paragraph","content":[{"type":"text","text":"M: My name’s Mips, a curious little one!"}]},{"type":"paragraph","content":[{"type":"text","text":"S: We are Sticks and Mips, the cat duo!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: You would think the two of you would rhyme at least, being a duo and all."}]},{"type":"paragraph","content":[{"type":"text","text":"L: What’s wrong, cat got your tongue?"}]},{"type":"paragraph","content":[{"type":"text","text":"S: I do not get the joke, you two must find a way to reach the top tree branch!"}]},{"type":"paragraph","content":[{"type":"text","text":"M: Yes, the top branch will earn our respect, if you can’t then no reward for you!"}]},{"type":"paragraph","content":[{"type":"text","text":"L: Ok, but how are we supposed to do that?"}]},{"type":"paragraph","content":[{"type":"text","text":"H: The top of the tree is too high for us, but I suppose we can try and find a way."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Mrs. Crow: Dialogue (Found ???)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, C = mrs. crow"}]},{"type":"paragraph","content":[{"type":"text","text":"C: Oh boo hoo, can’t anybody out there help me with my problem!"}]},{"type":"paragraph","content":[{"type":"text","text":"L: That depends, is the reward in it for us?"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Lyre! That’s no way to talk to someone in need, now tell us what your issue is."}]},{"type":"paragraph","content":[{"type":"text","text":"C: Well… the name’s Mrs. Crow and I just can’t find my husband anywhere!"}]},{"type":"paragraph","content":[{"type":"text","text":"L: “I don’t think I should tell her what happened…” (whispers)"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Where was the last place that you found them?"}]},{"type":"paragraph","content":[{"type":"text","text":"C: He… was set up to guard the eggs in the nest, but I just don’t know where he is now! Boo hoo hoo!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Alright alright, we’ll look for him."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"(Mr. crow can be found trapped under rubble in Firestone mountain, can be broken with a ground pound, the two talk in Firestone mountain)"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"H: We found him and brought him home to you, is there anything else you needed?"}]},{"type":"paragraph","content":[{"type":"text","text":"L: Oh no not another task…"}]},{"type":"paragraph","content":[{"type":"text","text":"C: No… Thank you so much for finding him, take this token that I had all along."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Kreakli Rhymes"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"While spooky spectres keep you at bay,"}]},{"type":"paragraph","content":[{"type":"text","text":"maybe I can finish my spell today!"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Halls like a labyrinth, floors made of wood,"}]},{"type":"paragraph","content":[{"type":"text","text":"get out of my mansion, you really should."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Have you had a chance to meet the ghosts inside,"}]},{"type":"paragraph","content":[{"type":"text","text":"you aren''t meant to be here, I thought I clarified."}]},{"type":"paragraph","content":[{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"H&L Key Locations on Island"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"3 Mist-side Castle;"}]},{"type":"paragraph","content":[{"type":"text","text":"-Graveyard (1)"}]},{"type":"paragraph","content":[{"type":"text","text":"-Mist-side Manor (2)"}]},{"type":"paragraph","content":[{"type":"text","text":"-Murky Walkways (3)"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Fixed Sabercat hat texture on eye"},{"type":"hardBreak"},{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"Mansion Layout"}]},{"type":"paragraph","content":[{"type":"text","text":"The main mansion is made up of four different layers, each containing keys to allow the player to complete the castle."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"The castle starts the player off in the main entrance. Once the player picks up the key, they can take it to the first door. After unlocking the [Entrance Door], players will be able to continue into the castle by walking down to the end of the hallway ahead. Players will pick up and use the [Kitchen Key] on the [Kitchen] Door which unlocks the [Kitchen]."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"Inside the [Kitchen] players 