INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(150,2,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bamboo Heights"}]},{"type":"paragraph","content":[{"type":"text","text":"A level filled with bamboo, temples, and heights."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]},{"type":"paragraph","content":[{"type":"text","text":"Friendlies:Mrs. Boot, Mr. Boot, Ren the Dwarf, Sammy Breadington, Cherry Lads, Springo, Earl D. Fly, Ritzy Rabbit, and Pocus."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]},{"type":"paragraph","content":[{"type":"text","text":"Baddies: Rootling, Shrublin, Click Clacka, Crusha’s, and The monkey boiz."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]},{"type":"paragraph","content":[{"type":"text","text":"Twisted Token Locations"}]},{"type":"paragraph","content":[{"type":"text","text":"1. Race through the hoop mini game to find a token."}]},{"type":"paragraph","content":[{"type":"text","text":"2. Beat the level boss, The Monkey Boiz to acquire a token."}]},{"type":"paragraph","content":[{"type":"text","text":"3. Get all Flazoozles in the level to get a twisted token."}]},{"type":"paragraph","content":[{"type":"text","text":"4. Inside the cave above to the monkey boy’s (Needs Monkey)"},{"type":"hardBreak"},{"type":"text","text":"5. Next to Pocus’s house on the hill."}]},{"type":"paragraph","content":[{"type":"text","text":"6. Talk with Earl D. Fly, get his cane, and return it to obtain a twisted token."}]},{"type":"paragraph","content":[{"type":"text","text":"7. At the bottom of the dried up fishing pond. "}]},{"type":"paragraph","content":[{"type":"text","text":"8. Top of temple"}]},{"type":"paragraph","content":[{"type":"text","text":"9. Get Mr. boot back to Mrs. boot"}]},{"type":"paragraph","content":[{"type":"text","text":"10. Behind Springo’s house"}]},{"type":"paragraph","content":[{"type":"text","text":"11. Inside Springo’s house"}]},{"type":"paragraph","content":[{"type":"text","text":"12. Catch the cherry lads mini game."}]},{"type":"paragraph","content":[{"type":"text","text":"13. On top of the fountain inside the temple."}]},{"type":"paragraph","content":[{"type":"text","text":"14. Climb up the vines at the tree house. (As a monkey)"}]},{"type":"paragraph","content":[{"type":"text","text":"15. Top of the cliff inside the house."}]},{"type":"paragraph","content":[{"type":"text","text":"16. Behind the web inside the cave."}]},{"type":"paragraph","content":[{"type":"text","text":"17.  Third floor inside the temple."}]},{"type":"paragraph","content":[{"type":"text","text":"18. Climb the vines on the left side of the temple. (As Monkey)"}]},{"type":"paragraph","content":[{"type":"text","text":"19. Race Ritzy Rabbit and win."}]},{"type":"paragraph","content":[{"type":"text","text":"20. Collect 10 Jellies for Sammy Breadington."}]},{"type":"paragraph","content":[{"type":"text","text":"Collectable Locations"}]},{"type":"paragraph","content":[{"type":"text","text":"PAges"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Defeat Ritzy in the race for the second time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Give Sammy BreadingTon 20 Jelly Jars"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Shoot Ladder down at base of mountain"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Panda coins"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the bench after you go over the first hill on the right."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hidden inside the three bamboo trunks near Mr. Boot."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Under Pocus’s House"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Pixies"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Behind Sammy Breadington’s Jelly jar."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Next to Pocus’s house."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Gold"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inside the cave around the entrance."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"At the back of the level right of Springo’s house."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"At the beginning on top of the hill close to Hugo"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Buggies"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the log next to the hoop mini game switch."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the hill next to the dried up pond."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On top of the dirt mound near the tree house."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On top of one of the cherry tree roots,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On top of the chopped down cherry tree next to the temple."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Pocus Tokens"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Behind Brs Boot’s barn"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"At the beginning of the level "}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On log behind the temple."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the cliffs near Mrs. Boot’s barn."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Near the Hoop mini game button."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the roots of the cherry tree."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"At the J near the Cherry lads."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"At the J near Pocus’s house."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Between the caves and tree house."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inside Pocus''s house through the chimney."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Cash"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"In the corner next to Earl De Fly."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Next to the mountain entrance."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On a bench at the base of the temple."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Secret Floppy Location"}]},{"type":"paragraph","content":[{"type":"text","text":"Behind the poster/flag inside the tree house, must hit gong before going inside it."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]},{"type":"paragraph","content":[{"type":"text","text":"Fruit Fly: Dialogue"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, F = fruit fly"}]},{"type":"paragraph","content":[{"type":"text","text":"F: Hi Harper and Lyre, you two are the best!"}]},{"type":"paragraph","content":[{"type":"text","text":"L: Well well well, this is what im talking about, our own fan club."}]},{"type":"paragraph","content":[{"type":"text","text":"F: I’ll be your fan as long as I live!"}]},{"type":"paragraph","content":[{"type":"text","text":"F: Can you help me by finding me a cane for when I get old?"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Anything for a fan, come on Lyre, let''s help him."}]},{"type":"paragraph","content":[{"type":"text","text":"L: I mean he is our fan, so that works for me."}]},{"type":"paragraph","content":[{"type":"text","text":"(Player gives them Cane)"}]},{"type":"paragraph","content":[{"type":"text","text":"F: Thanks guys, that’s why I''m your biggest fan!"}]},{"type":"paragraph","content":[{"type":"text","text":"F: If you wouldn’t mind, I can’t use this cane with you watching."}]},{"type":"paragraph","content":[{"type":"text","text":"(Player leaves and comes back)"}]},{"type":"paragraph","content":[{"type":"text","text":"F: Well look who it is, Harper and Lyre!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: What happened to you, we just left?"}]},{"type":"paragraph","content":[{"type":"text","text":"F: We fruit flies age fast, but not to worry as I still have my wits."}]},{"type":"paragraph","content":[{"type":"text","text":"L: What you have is bad genetics..."}]},{"type":"paragraph","content":[{"type":"text","text":"H: Lyre don''t be rude."}]},{"type":"paragraph","content":[{"type":"text","text":"F: It''s ok, thank you for helping me, now here''s a token."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren the Dwarf: Dialogue"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: Well now what do we have here, a couple of punks. What do you want?"},{"type":"hardBreak"},{"type":"text","text":"Lyre: I like this guy Harper. He reminds me of me."}]},{"type":"paragraph","content":[{"type":"text","text":"Harper: Sorry for bothering you."}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: First a giant tree attacks me, now a dumb otter annoys me."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: Let''s go, Harper. This guy is an angry little elf."}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: ELF?! Are you out of your mind!"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: If I had my ore I would not be here right now."}]},{"type":"paragraph","content":[{"type":"text","text":"Harper: Settle down you two, what happened?"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: This giant tree tricked me and stole the last 5 pieces of my ore."}]},{"type":"paragraph","content":[{"type":"text","text":"Harper: What can we do to help?"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: Get my ore inside the house up the mountain, but watch out for Crusha''s."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: What''s a Crusha? It sounds dumb, like you."}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: It''s a big rock, they crush you. Sent me flying last week."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: What''s in it for us?"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: I''ve got this wooden doo-dad that I was going to burn."}]},{"type":"paragraph","content":[{"type":"text","text":"Harper: That sounds like a deal, don''t worry Ren we will help you."}]},{"type":"paragraph","content":[{"type":"text","text":"—----------------------------------------------------------Second Ren—-------"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: Took you long enough. Did you get my emeralds?"}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: We got your rubies, not your emeralds."}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: Rubies? These are clearly emeralds."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: What, no way, these are rubies!"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: You must be color blind, these are emeralds."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: You’ve lost it Ren, just give us the token."}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: Even though you''re blind and dumb, you helped me so here."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]}]}','Dragonfirebane','2026-08-03 23:46:02');
INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(151,7,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Harper and lyre the main duo of the game, both together they must defeat kreakli and save goombalombie island."}]}]}','Dragonfirebane','2026-08-03 23:48:37');
INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(154,79,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"There are a total of 5 in each world."},{"type":"hardBreak"},{"type":"text","text":"They are used in gaining additional oxygen from Bufweeble."}]}]}','Dragonfirebane','2026-08-04 00:52:35');
INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(155,34,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mrs. Crow: Dialogue (Found ???)"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, C = mrs. crow"}]},{"type":"paragraph","content":[{"type":"text","text":"C: Oh boo hoo, can’t anybody out there help me with my problem!"}]},{"type":"paragraph","content":[{"type":"text","text":"L: That depends, is the reward in it for us?"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Lyre! That’s no way to talk to someone in need, now tell us what your issue is."}]},{"type":"paragraph","content":[{"type":"text","text":"C: Well… the name’s Mrs. Crow and I just can’t find my husband anywhere!"}]},{"type":"paragraph","content":[{"type":"text","text":"L: “I don’t think I should tell her what happened…” (whispers)"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Where was the last place that you found them?"}]},{"type":"paragraph","content":[{"type":"text","text":"C: He… was set up to guard the eggs in the nest, but I just don’t know where he is now! Boo hoo hoo!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Alright alright, we’ll look for him."}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"(Mr. crow can be found trapped under rubble in Firestone mountain, can be broken with a ground pound, the two talk in Firestone mountain)"}]},{"type":"paragraph","content":[{"type":"hardBreak"}]},{"type":"paragraph","content":[{"type":"text","text":"H: We found him and brought him home to you, is there anything else you needed?"}]},{"type":"paragraph","content":[{"type":"text","text":"L: Oh no not another task…"}]},{"type":"paragraph","content":[{"type":"text","text":"C: No… Thank you so much for finding him, take this token that I had all along."}]}]}','Dragonfirebane','2026-08-04 00:54:25');
INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(156,34,'<p>Mrs. Crow: Dialogue (Found ???)</p><p>Key: Harper = H, Lyre = L, C = mrs. crow</p><p>C: Oh boo hoo, can’t anybody out there help me with my problem!</p><p>L: That depends, is the reward in it for us?</p><p>H: Lyre! That’s no way to talk to someone in need, now tell us what your issue is.</p><p>C: Well… the name’s Mrs. Crow and I just can’t find my husband anywhere!</p><p>L: “I don’t think I should tell her what happened…” (whispers)</p><p>H: Where was the last place that you found them?</p><p>C: He… was set up to guard the eggs in the nest, but I just don’t know where he is now! Boo hoo hoo!</p><p>H: Alright alright, we’ll look for him.</p><p>&nbsp;</p><p>(Mr. crow can be found trapped under rubble in Firestone mountain, can be broken with a ground pound, the two talk in Firestone mountain)</p><p>&nbsp;</p><p>H: We found him and brought him home to you, is there anything else you needed?</p><p>L: Oh no not another task…</p><p>C: No… Thank you so much for finding him, take this token that I had all along.</p>','Sam','2026-08-04 00:54:35');
INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(159,2,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bamboo Heights"}]},{"type":"paragraph","content":[{"type":"text","text":"A level filled with bamboo, temples, and heights."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]},{"type":"paragraph","content":[{"type":"text","text":"Friendlies:Mrs. Boot, Mr. Boot, Ren the Dwarf, Sammy Breadington, Cherry Lads, Springo, Earl D. Fly, Ritzy Rabbit, and Pocus."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]},{"type":"paragraph","content":[{"type":"text","text":"Baddies: Rootling, Shrublin, Click Clacka, Crusha’s, and The monkey boiz."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]},{"type":"paragraph","content":[{"type":"text","text":"Twisted Token Locations"}]},{"type":"paragraph","content":[{"type":"text","text":"1. Race through the hoop mini game to find a token."}]},{"type":"paragraph","content":[{"type":"text","text":"2. Beat the level boss, The Monkey Boiz to acquire a token."}]},{"type":"paragraph","content":[{"type":"text","text":"3. Get all Flazoozles in the level to get a twisted token."}]},{"type":"paragraph","content":[{"type":"text","text":"4. Inside the cave above to the monkey boy’s (Needs Monkey)"},{"type":"hardBreak"},{"type":"text","text":"5. Next to Pocus’s house on the hill."}]},{"type":"paragraph","content":[{"type":"text","text":"6. Talk with Earl D. Fly, get his cane, and return it to obtain a twisted token."}]},{"type":"paragraph","content":[{"type":"text","text":"7. At the bottom of the dried up fishing pond. "}]},{"type":"paragraph","content":[{"type":"text","text":"8. Top of temple"}]},{"type":"paragraph","content":[{"type":"text","text":"9. Get Mr. boot back to Mrs. boot"}]},{"type":"paragraph","content":[{"type":"text","text":"10. Behind Springo’s house"}]},{"type":"paragraph","content":[{"type":"text","text":"11. Inside Springo’s house"}]},{"type":"paragraph","content":[{"type":"text","text":"12. Catch the cherry lads mini game."}]},{"type":"paragraph","content":[{"type":"text","text":"13. On top of the fountain inside the temple."}]},{"type":"paragraph","content":[{"type":"text","text":"14. Climb up the vines at the tree house. (As a monkey)"}]},{"type":"paragraph","content":[{"type":"text","text":"15. Top of the cliff inside the house."}]},{"type":"paragraph","content":[{"type":"text","text":"16. Behind the web inside the cave."}]},{"type":"paragraph","content":[{"type":"text","text":"17.  Third floor inside the temple."}]},{"type":"paragraph","content":[{"type":"text","text":"18. Climb the vines on the left side of the temple. (As Monkey)"}]},{"type":"paragraph","content":[{"type":"text","text":"19. Race Ritzy Rabbit and win."}]},{"type":"paragraph","content":[{"type":"text","text":"20. Collect 10 Jellies for Sammy Breadington."}]},{"type":"paragraph","content":[{"type":"text","text":"Collectable Locations"}]},{"type":"paragraph","content":[{"type":"text","text":"PAges"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Defeat Ritzy in the race for the second time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Give Sammy BreadingTon 20 Jelly Jars"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Shoot Ladder down at base of mountain"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Panda coins"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the bench after you go over the first hill on the right."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hidden inside the three bamboo trunks near Mr. Boot."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Under Pocus’s House"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Pixies"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Behind Sammy Breadington’s Jelly jar."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Next to Pocus’s house."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Gold"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inside the cave around the entrance."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"At the back of the level right of Springo’s house."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"At the beginning on top of the hill close to Hugo"}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Buggies"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the log next to the hoop mini game switch."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the hill next to the dried up pond."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On top of the dirt mound near the tree house."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On top of one of the cherry tree roots,"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On top of the chopped down cherry tree next to the temple."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Pocus Tokens"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Behind Brs Boot’s barn"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"At the beginning of the level "}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On log behind the temple."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the cliffs near Mrs. Boot’s barn."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Near the Hoop mini game button."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the roots of the cherry tree."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"At the J near the Cherry lads."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"At the J near Pocus’s house."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Between the caves and tree house."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inside Pocus''s house through the chimney."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Cash"}]},{"type":"orderedList","attrs":{"start":1,"type":null},"content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"In the corner next to Earl De Fly."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Next to the mountain entrance."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On a bench at the base of the temple."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Secret Floppy Location"}]},{"type":"paragraph","content":[{"type":"text","text":"Behind the poster/flag inside the tree house, must hit gong before going inside it."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]},{"type":"paragraph","content":[{"type":"text","text":"Fruit Fly: Dialogue"}]},{"type":"paragraph","content":[{"type":"text","text":"Key: Harper = H, Lyre = L, F = fruit fly"}]},{"type":"paragraph","content":[{"type":"text","text":"F: Hi Harper and Lyre, you two are the best!"}]},{"type":"paragraph","content":[{"type":"text","text":"L: Well well well, this is what im talking about, our own fan club."}]},{"type":"paragraph","content":[{"type":"text","text":"F: I’ll be your fan as long as I live!"}]},{"type":"paragraph","content":[{"type":"text","text":"F: Can you help me by finding me a cane for when I get old?"}]},{"type":"paragraph","content":[{"type":"text","text":"H: Anything for a fan, come on Lyre, let''s help him."}]},{"type":"paragraph","content":[{"type":"text","text":"L: I mean he is our fan, so that works for me."}]},{"type":"paragraph","content":[{"type":"text","text":"(Player gives them Cane)"}]},{"type":"paragraph","content":[{"type":"text","text":"F: Thanks guys, that’s why I''m your biggest fan!"}]},{"type":"paragraph","content":[{"type":"text","text":"F: If you wouldn’t mind, I can’t use this cane with you watching."}]},{"type":"paragraph","content":[{"type":"text","text":"(Player leaves and comes back)"}]},{"type":"paragraph","content":[{"type":"text","text":"F: Well look who it is, Harper and Lyre!"}]},{"type":"paragraph","content":[{"type":"text","text":"H: What happened to you, we just left?"}]},{"type":"paragraph","content":[{"type":"text","text":"F: We fruit flies age fast, but not to worry as I still have my wits."}]},{"type":"paragraph","content":[{"type":"text","text":"L: What you have is bad genetics..."}]},{"type":"paragraph","content":[{"type":"text","text":"H: Lyre don''t be rude."}]},{"type":"paragraph","content":[{"type":"text","text":"F: It''s ok, thank you for helping me, now here''s a token."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren the Dwarf: Dialogue"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: Well now what do we have here, a couple of punks. What do you want?"},{"type":"hardBreak"},{"type":"text","text":"Lyre: I like this guy Harper. He reminds me of me."}]},{"type":"paragraph","content":[{"type":"text","text":"Harper: Sorry for bothering you."}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: First a giant tree attacks me, now a dumb otter annoys me."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: Let''s go, Harper. This guy is an angry little elf."}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: ELF?! Are you out of your mind!"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: If I had my ore I would not be here right now."}]},{"type":"paragraph","content":[{"type":"text","text":"Harper: Settle down you two, what happened?"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: This giant tree tricked me and stole the last 5 pieces of my ore."}]},{"type":"paragraph","content":[{"type":"text","text":"Harper: What can we do to help?"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: Get my ore inside the house up the mountain, but watch out for Crusha''s."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: What''s a Crusha? It sounds dumb, like you."}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: It''s a big rock, they crush you. Sent me flying last week."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: What''s in it for us?"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: I''ve got this wooden doo-dad that I was going to burn."}]},{"type":"paragraph","content":[{"type":"text","text":"Harper: That sounds like a deal, don''t worry Ren we will help you."}]},{"type":"paragraph","content":[{"type":"text","text":"—----------------------------------------------------------Second Ren—-------"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: Took you long enough. Did you get my emeralds?"}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: We got your rubies, not your emeralds."}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: Rubies? These are clearly emeralds."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: What, no way, these are rubies!"}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: You must be color blind, these are emeralds."}]},{"type":"paragraph","content":[{"type":"text","text":"Lyre: You’ve lost it Ren, just give us the token."}]},{"type":"paragraph","content":[{"type":"text","text":"Ren: Even though you''re blind and dumb, you helped me so here."}]},{"type":"paragraph","content":[{"type":"text","text":"_________________________________________________________________________________"}]}]}','Sam','2026-08-04 01:57:56');
INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(160,2,'<p>Bamboo Heights</p><p>A level filled with bamboo, temples, and heights.</p><p>_________________________________________________________________________________</p><p>Friendlies:Mrs. Boot, Mr. Boot, Ren the Dwarf, Sammy Breadington, Cherry Lads, Springo, Earl D. Fly, Ritzy Rabbit, and Pocus.</p><p>_________________________________________________________________________________</p><p>Baddies: Rootling, Shrublin, Click Clacka, Crusha’s, and The monkey boiz.</p><p>_________________________________________________________________________________</p><p>Twisted Token Locations</p><p>1. Race through the hoop mini game to find a token.</p><p>2. Beat the level boss, The Monkey Boiz to acquire a token.</p><p>3. Get all Flazoozles in the level to get a twisted token.</p><p>4. Inside the cave above to the monkey boy’s (Needs Monkey)<br>5. Next to Pocus’s house on the hill.</p><p>6. Talk with Earl D. Fly, get his cane, and return it to obtain a twisted token.</p><p>7. At the bottom of the dried up fishing pond.&nbsp;</p><p>8. Top of temple</p><p>9. Get Mr. boot back to Mrs. boot</p><p>10. Behind Springo’s house</p><p>11. Inside Springo’s house</p><p>12. Catch the cherry lads mini game.</p><p>13. On top of the fountain inside the temple.</p><p>14. Climb up the vines at the tree house. (As a monkey)</p><p>15. Top of the cliff inside the house.</p><p>16. Behind the web inside the cave.</p><p>17.&nbsp; Third floor inside the temple.</p><p>18. Climb the vines on the left side of the temple. (As Monkey)</p><p>19. Race Ritzy Rabbit and win.</p><p>20. Collect 10 Jellies for Sammy Breadington.</p><p>Collectable Locations</p><p>PAges</p><ol><li data-list-item-id="e78fdca970c9597cb02dfc6dd4a55963f">Defeat Ritzy in the race for the second time.</li><li data-list-item-id="ece3698954c6401c6c554f26826942239">Give Sammy BreadingTon 20 Jelly Jars</li><li data-list-item-id="ef87d2e694cd96fc22cc5fabcbefed5a3">Shoot Ladder down at base of mountain</li></ol><p>Panda coins</p><ol><li data-list-item-id="e70b8cb794277bbbc42d8dfb573ab37f2">On the bench after you go over the first hill on the right.</li><li data-list-item-id="eadfcb243017c368873a581291cba4e7f">Hidden inside the three bamboo trunks near Mr. Boot.</li><li data-list-item-id="eb3636d04b0c52ed706c4e901e3a522d0">Under Pocus’s House</li></ol><p>Pixies</p><ol><li data-list-item-id="e6ec053b37e5c347dbc1bea631550f711">Behind Sammy Breadington’s Jelly jar.</li><li data-list-item-id="e2ce61efb8ca742f43ba03c53a23f7f70">Next to Pocus’s house.</li></ol><p>Gold</p><ol><li data-list-item-id="e0da0d2fe9c37a7472aa741cc7ceb0568">Inside the cave around the entrance.</li><li data-list-item-id="e0b994f9f20dfcc3cf86f3ccc37e7bfe7">At the back of the level right of Springo’s house.</li><li data-list-item-id="ec87d36ecb79bee100039f3705bdf2bcd">At the beginning on top of the hill close to Hugo</li></ol><p>Buggies</p><ol><li data-list-item-id="efa45f780bbdb7742b38202b2ecd5b995">On the log next to the hoop mini game switch.</li><li data-list-item-id="e13bd176459daffd87bbbae529cd00605">On the hill next to the dried up pond.</li><li data-list-item-id="e3e8d18d54673f77a6f6c4f1e40883299">On top of the dirt mound near the tree house.</li><li data-list-item-id="ee7825245c713a80741d64869fdd0e8ab">On top of one of the cherry tree roots,</li><li data-list-item-id="ed8ad26cabf4c58713ffbd4d34842c83f">On top of the chopped down cherry tree next to the temple.</li></ol><p>Pocus Tokens</p><ol><li data-list-item-id="ebc085d67abefd5d5e78a50115370cf13">Behind Brs Boot’s barn</li><li data-list-item-id="e79646f59418aad2721a2967497addc76">At the beginning of the level&nbsp;</li><li data-list-item-id="ef279b363c746b41e491b7ab904d591de">On log behind the temple.</li><li data-list-item-id="e1eb927d122f7b95f5f748fed6a0b65a1">On the cliffs near Mrs. Boot’s barn.</li><li data-list-item-id="ef6de12f3a4ab4bf3e76707db27279516">Near the Hoop mini game button.</li><li data-list-item-id="e48802ce97f0b7062af0b67102fb06b64">On the roots of the cherry tree.</li><li data-list-item-id="e8d580d6677b95d06c6695258d33bb3b1">At the J near the Cherry lads.</li><li data-list-item-id="e1663940fa2bd0101cac9b43e75dbcb9a">At the J near Pocus’s house.</li><li data-list-item-id="e24459a429a5c11df797ce20dd5abc953">Between the caves and tree house.</li><li data-list-item-id="edb6288b5f79dc5f80e49955bc799a8cb">Inside Pocus''s house through the chimney.</li></ol><p>Cash</p><ol><li data-list-item-id="e30594d063ba960b36e948af0e97e75fc">In the corner next to Earl De Fly.</li><li data-list-item-id="e66e39682902dbc265843bd28047a6bf6">Next to the mountain entrance.</li><li data-list-item-id="edc525b7a66fd53316a5769f0458b79d3">On a bench at the base of the temple.</li></ol><p>Secret Floppy Location</p><p>Behind the poster/flag inside the tree house, must hit gong before going inside it.</p><p>_________________________________________________________________________________</p><p>Fruit Fly: Dialogue</p><p>Key: Harper = H, Lyre = L, F = fruit fly</p><p>F: Hi Harper and Lyre, you two are the best!</p><p>L: Well well well, this is what im talking about, our own fan club.</p><p>F: I’ll be your fan as long as I live!</p><p>F: Can you help me by finding me a cane for when I get old?</p><p>H: Anything for a fan, come on Lyre, let''s help him.</p><p>L: I mean he is our fan, so that works for me.</p><p>(Player gives them Cane)</p><p>F: Thanks guys, that’s why I''m your biggest fan!</p><p>F: If you wouldn’t mind, I can’t use this cane with you watching.</p><p>(Player leaves and comes back)</p><p>F: Well look who it is, Harper and Lyre!</p><p>H: What happened to you, we just left?</p><p>F: We fruit flies age fast, but not to worry as I still have my wits.</p><p>L: What you have is bad genetics...</p><p>H: Lyre don''t be rude.</p><p>F: It''s ok, thank you for helping me, now here''s a token.</p><p>_________________________________________________________________________________</p><p>Ren the Dwarf: Dialogue</p><p>Ren: Well now what do we have here, a couple of punks. What do you want?<br>Lyre: I like this guy Harper. He reminds me of me.</p><p>Harper: Sorry for bothering you.</p><p>Ren: First a giant tree attacks me, now a dumb otter annoys me.</p><p>Lyre: Let''s go, Harper. This guy is an angry little elf.</p><p>Ren: ELF?! Are you out of your mind!</p><p>Ren: If I had my ore I would not be here right now.</p><p>Harper: Settle down you two, what happened?</p><p>Ren: This giant tree tricked me and stole the last 5 pieces of my ore.</p><p>Harper: What can we do to help?</p><p>Ren: Get my ore inside the house up the mountain, but watch out for Crusha''s.</p><p>Lyre: What''s a Crusha? It sounds dumb, like you.</p><p>Ren: It''s a big rock, they crush you. Sent me flying last week.</p><p>Lyre: What''s in it for us?</p><p>Ren: I''ve got this wooden doo-dad that I was going to burn.</p><p>Harper: That sounds like a deal, don''t worry Ren we will help you.</p><p>—----------------------------------------------------------Second Ren—-------</p><p>Ren: Took you long enough. Did you get my emeralds?</p><p>Lyre: We got your rubies, not your emeralds.</p><p>Ren: Rubies? These are clearly emeralds.</p><p>Lyre: What, no way, these are rubies!</p><p>Ren: You must be color blind, these are emeralds.</p><p>Lyre: You’ve lost it Ren, just give us the token.</p><p>Ren: Even though you''re blind and dumb, you helped me so here.</p><p>_________________________________________________________________________________</p>','Sam','2026-08-04 01:58:22');
INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(161,2,'<p>Bamboo Heights</p><p>A level filled with bamboo, temples, and heights.</p><p>Friendlies: Mrs. Boot, Mr. Boot, Ren the Dwarf, Sammy Breadington, Cherry Lads, Springo, Earl D. Fly, Ritzy Rabbit, and Pocus.</p><p>_________________________________________________________________________________</p><p>Baddies: Rootling, Shrublin, Click Clacka, Crusha’s, and The monkey boiz.</p><p>_________________________________________________________________________________</p><p>Twisted Token Locations</p><p>1. Race through the hoop mini game to find a token.</p><p>2. Beat the level boss, The Monkey Boiz to acquire a token.</p><p>3. Get all Flazoozles in the level to get a twisted token.</p><p>4. Inside the cave above to the monkey boy’s (Needs Monkey)<br>5. Next to Pocus’s house on the hill.</p><p>6. Talk with Earl D. Fly, get his cane, and return it to obtain a twisted token.</p><p>7. At the bottom of the dried up fishing pond.&nbsp;</p><p>8. Top of temple</p><p>9. Get Mr. boot back to Mrs. boot</p><p>10. Behind Springo’s house</p><p>11. Inside Springo’s house</p><p>12. Catch the cherry lads mini game.</p><p>13. On top of the fountain inside the temple.</p><p>14. Climb up the vines at the tree house. (As a monkey)</p><p>15. Top of the cliff inside the house.</p><p>16. Behind the web inside the cave.</p><p>17.&nbsp; Third floor inside the temple.</p><p>18. Climb the vines on the left side of the temple. (As Monkey)</p><p>19. Race Ritzy Rabbit and win.</p><p>20. Collect 10 Jellies for Sammy Breadington.</p><p>Collectable Locations</p><p>PAges</p><ol><li data-list-item-id="e78fdca970c9597cb02dfc6dd4a55963f">Defeat Ritzy in the race for the second time.</li><li data-list-item-id="ece3698954c6401c6c554f26826942239">Give Sammy BreadingTon 20 Jelly Jars</li><li data-list-item-id="ef87d2e694cd96fc22cc5fabcbefed5a3">Shoot Ladder down at base of mountain</li></ol><p>Panda coins</p><ol><li data-list-item-id="e70b8cb794277bbbc42d8dfb573ab37f2">On the bench after you go over the first hill on the right.</li><li data-list-item-id="eadfcb243017c368873a581291cba4e7f">Hidden inside the three bamboo trunks near Mr. Boot.</li><li data-list-item-id="eb3636d04b0c52ed706c4e901e3a522d0">Under Pocus’s House</li></ol><p>Pixies</p><ol><li data-list-item-id="e6ec053b37e5c347dbc1bea631550f711">Behind Sammy Breadington’s Jelly jar.</li><li data-list-item-id="e2ce61efb8ca742f43ba03c53a23f7f70">Next to Pocus’s house.</li></ol><p>Gold</p><ol><li data-list-item-id="e0da0d2fe9c37a7472aa741cc7ceb0568">Inside the cave around the entrance.</li><li data-list-item-id="e0b994f9f20dfcc3cf86f3ccc37e7bfe7">At the back of the level right of Springo’s house.</li><li data-list-item-id="ec87d36ecb79bee100039f3705bdf2bcd">At the beginning on top of the hill close to Hugo</li></ol><p>Buggies</p><ol><li data-list-item-id="efa45f780bbdb7742b38202b2ecd5b995">On the log next to the hoop mini game switch.</li><li data-list-item-id="e13bd176459daffd87bbbae529cd00605">On the hill next to the dried up pond.</li><li data-list-item-id="e3e8d18d54673f77a6f6c4f1e40883299">On top of the dirt mound near the tree house.</li><li data-list-item-id="ee7825245c713a80741d64869fdd0e8ab">On top of one of the cherry tree roots,</li><li data-list-item-id="ed8ad26cabf4c58713ffbd4d34842c83f">On top of the chopped down cherry tree next to the temple.</li></ol><p>Pocus Tokens</p><ol><li data-list-item-id="ebc085d67abefd5d5e78a50115370cf13">Behind Brs Boot’s barn</li><li data-list-item-id="e79646f59418aad2721a2967497addc76">At the beginning of the level&nbsp;</li><li data-list-item-id="ef279b363c746b41e491b7ab904d591de">On log behind the temple.</li><li data-list-item-id="e1eb927d122f7b95f5f748fed6a0b65a1">On the cliffs near Mrs. Boot’s barn.</li><li data-list-item-id="ef6de12f3a4ab4bf3e76707db27279516">Near the Hoop mini game button.</li><li data-list-item-id="e48802ce97f0b7062af0b67102fb06b64">On the roots of the cherry tree.</li><li data-list-item-id="e8d580d6677b95d06c6695258d33bb3b1">At the J near the Cherry lads.</li><li data-list-item-id="e1663940fa2bd0101cac9b43e75dbcb9a">At the J near Pocus’s house.</li><li data-list-item-id="e24459a429a5c11df797ce20dd5abc953">Between the caves and tree house.</li><li data-list-item-id="edb6288b5f79dc5f80e49955bc799a8cb">Inside Pocus''s house through the chimney.</li></ol><p>Cash</p><ol><li data-list-item-id="e30594d063ba960b36e948af0e97e75fc">In the corner next to Earl De Fly.</li><li data-list-item-id="e66e39682902dbc265843bd28047a6bf6">Next to the mountain entrance.</li><li data-list-item-id="edc525b7a66fd53316a5769f0458b79d3">On a bench at the base of the temple.</li></ol><p>Secret Floppy Location</p><p>Behind the poster/flag inside the tree house, must hit gong before going inside it.</p><p>_________________________________________________________________________________</p><p>Fruit Fly: Dialogue</p><p>Key: Harper = H, Lyre = L, F = fruit fly</p><p>F: Hi Harper and Lyre, you two are the best!</p><p>L: Well well well, this is what im talking about, our own fan club.</p><p>F: I’ll be your fan as long as I live!</p><p>F: Can you help me by finding me a cane for when I get old?</p><p>H: Anything for a fan, come on Lyre, let''s help him.</p><p>L: I mean he is our fan, so that works for me.</p><p>(Player gives them Cane)</p><p>F: Thanks guys, that’s why I''m your biggest fan!</p><p>F: If you wouldn’t mind, I can’t use this cane with you watching.</p><p>(Player leaves and comes back)</p><p>F: Well look who it is, Harper and Lyre!</p><p>H: What happened to you, we just left?</p><p>F: We fruit flies age fast, but not to worry as I still have my wits.</p><p>L: What you have is bad genetics...</p><p>H: Lyre don''t be rude.</p><p>F: It''s ok, thank you for helping me, now here''s a token.</p><p>_________________________________________________________________________________</p><p>Ren the Dwarf: Dialogue</p><p>Ren: Well now what do we have here, a couple of punks. What do you want?<br>Lyre: I like this guy Harper. He reminds me of me.</p><p>Harper: Sorry for bothering you.</p><p>Ren: First a giant tree attacks me, now a dumb otter annoys me.</p><p>Lyre: Let''s go, Harper. This guy is an angry little elf.</p><p>Ren: ELF?! Are you out of your mind!</p><p>Ren: If I had my ore I would not be here right now.</p><p>Harper: Settle down you two, what happened?</p><p>Ren: This giant tree tricked me and stole the last 5 pieces of my ore.</p><p>Harper: What can we do to help?</p><p>Ren: Get my ore inside the house up the mountain, but watch out for Crusha''s.</p><p>Lyre: What''s a Crusha? It sounds dumb, like you.</p><p>Ren: It''s a big rock, they crush you. Sent me flying last week.</p><p>Lyre: What''s in it for us?</p><p>Ren: I''ve got this wooden doo-dad that I was going to burn.</p><p>Harper: That sounds like a deal, don''t worry Ren we will help you.</p><p>—----------------------------------------------------------Second Ren—-------</p><p>Ren: Took you long enough. Did you get my emeralds?</p><p>Lyre: We got your rubies, not your emeralds.</p><p>Ren: Rubies? These are clearly emeralds.</p><p>Lyre: What, no way, these are rubies!</p><p>Ren: You must be color blind, these are emeralds.</p><p>Lyre: You’ve lost it Ren, just give us the token.</p><p>Ren: Even though you''re blind and dumb, you helped me so here.</p><p>_________________________________________________________________________________</p>','Sam','2026-08-04 02:00:40');
INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(162,2,'<p>Harper and Lyre''s first level you''ll adventure through. Bamboo Heights features bamboo, temples, and high heights.</p><p><strong>Friendlies:</strong> Mrs. Boot, Mr. Boot, Ren the Dwarf, Sammy Breadington, Cherry Lads, Springo, Earl D. Fly, Ritzy Rabbit, and Pocus.</p><p><strong>Baddies:</strong> Rootling, Shrublin, Click Clacka, Crusha’s, and The monkey boiz.</p>','Sam','2026-08-04 02:01:22');
