INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(168,22,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The fruit fly is located inside Bamboo Heights. With his short life span he asks the player for a cane in which the player watches him die shortly after walking around the corner."}]}]}','Dragonfirebane','2026-08-04 02:08:14');
