INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(173,49,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The main villain of the game, the dark one kreakli. He was trapped away inside the pale moonstone. After the festival of the sealing, Gobbo stole the moonstone and placed it within the dark heart of the oak tree. Kreakli came alive and began his path of destruction, starting with Gobbo."},{"type":"hardBreak"},{"type":"hardBreak"},{"type":"text","text":"In a way he''s like bill from gravity falls. But his lore is simple, he is just a jerk."}]}]}','Dragonfirebane','2026-09-07 17:59:33');
INSERT INTO "revisions" ("id","page_id","content","edited_by","edited_at") VALUES(174,126,'<p>Sligma is the boss of Firestone Mountain, and shoots fire balls into the air like a shower of fire rocks.</p>','Dragonfirebane','2026-09-07 18:02:33');
